window.PMM_NAHJ_TRANSCRIPT_ACCEPT({"group":"sermons","number":1,"source":"خطبه 1.docx","mode":"explicit-parts","parts":["خطبه اول \nبخش اول:\n\nمتن:\nالْحَمْدُ لِلَّهِ الَّذِی لَا یَبْلُغُ مِدْحَتَهُ الْقَائِلُونَ وَ لَا یحْصِی نَعْمَاءَهُ الْعَادُّونَ وَ لَا یؤَدِّی حَقَّهُ الْمُجْتَهِدُونَ الَّذِی لَا یدْرِکهُ بُعْدُ الْهِمَمِ وَ لَا ینَالُهُ غَوْصُ الْفِطَنِ \n\nترجمه:\nستایش مخصوص خداوندی است که ستایشگران هرگز به مدح و ثنای او نمی‌رسند و حسابگران (زبردست) هرگز نعمت‌هایش را شماره نمی‌کنند و تلاش‌گران هرگز قادر به ادای حقّ او نیستند. همان خدایی که افکار بلند و ژرف‌اندیش، کنه ذاتش را درک نکند و غوّاصان هوشمند (دریای علوم و دانش‌ها) دسترسی به کمال هستی‌اش پیدا ننمایند\n\nتفسیر:\n💠الْحَمْدُ لِلَّهِ الَّذِی لَا یبْلُغُ مِدْحَتَهُ الْقَائِلُونَ\nحمد و شکر مخصوص خدای است که همه ثنا گویان، سخنوران، مداحان، نمی‌توانند به حد اعلای مدح برسند\nهیچ قائلی نتواند حد مدح الهی را بجا آورد\nهر کس به‌قدر درک، فهم، ظرفیت و طهارت خود حمد و ثنای خدا دارد\nدر علوم‌تجربی هرچه بیشتر مطالعه شود و بداند درک بیشتر می‌شود\nهرچه بیشتر خوانده شود علوم بیشتر می‌شود\nاما در علم توحیدی علاوه بر فکر، اندیشه، تحصیل، یک بخش مهم آن طهارت است\nاگر طهارت باشد چیزهایی می‌دهند که با خواندن حاصل نمی‌شود\nبسیاری دسترسی به عالم غیب پیدا کردند\nهر شخصی به‌قدر وسع و فهم خدا را مدح می‌کند، اما خدا به‌اندازۀ فهم و حد ما نیست\nخدا که محدود نیست برای او حدی از مدح و ثنا قائل باشیم\n💠وَ لَا یحْصِی نَعْمَاءَهُ الْعَادُّونَ\nحمد مخصوص خدایی که، \nحسابگران نتوانند نعمت‌های او را بشمارش در آورن\nحتی با دستگاه‌های پیشرفته شمارش ممکن نیست\nنعمت‌های محسوس و ملموس که به طور عادی با آن سروکار داریم \n نعمت ظرافت‌هایی که در جسم بکار رفته\nنعمت‌های ظاهری، احساسات درونی، \n فهم گرسنگی، خواب، حتی درد یک نعمت است\nاحساس درد گرچه تلخ است؛ اما درون آن نعمتی است ناشناخته\nشمارش گران نتوانند حتی نعمت ظاهر را شمارش کنند، چه برسد به نعمت‌های پنهان که از آن بی‌خبریم\nاینکه تفکر، تعقل، ظرفیت رشد داریم نعمت‌های ناشناخته‌اند \nبماند که چه نیروهایی که خدا موظف کرده مراقب ما باشند\nو چه نیروهای معنوی که عامل سرپا نگه‌داشتن ما هستند و از آنها بی‌خبریم\nچه کسی قادر بر شمارش است\n💠وَ لَا یؤَدِّی حَقَّهُ الْمُجْتَهِدُونَ\nشکر مخصوص خدایی که \nمجتهدان و تلاش‌گران حق خدا را نمی‌توانند ادا کنند\nاین سه جمله پشت‌هم؛ \nوقتی نتوان نعمت را شمارش کرد، \n وقتی نتوان نعمت را بیان کرد، \nچطور می‌شود در عمل حق آن را ادا کرد\nچگونه می‌توان نعمت را شناخت و حق آن را ادا کرد\nاز جهت عملیاتی و خارجی نمی‌توانید حق خدا را ادا کنید\nاز آن بالاتر نمی‌توانید خدا را بفهمید. بافکر، تخیل، وهم، اندیشه، نخواهید فهمید\n💠اَلَّذِی لَا یدْرِکهُ بُعْدُ الْهِمَمِ \nهم در لغت به معنای ذوب کردن است\nهم چیزی که در وجود انسان او را ذوب می‌کند و در یک مسیر او را متمرکز می‌کند و از چند راهه باز می‌دارد\nحمد مختص خدایی که \nهمت‌های بلند در مقابل فهم خدا عاجزند\nخود را در راه شناخت خدا ذوب کنند باز نمی‌توانند به آن برسند\n💠وَ لَا ینَالُهُ غَوْصُ الْفِطَنِ\nغواصان دریای زیرکی که به‌ظاهر اکتفا نکرده و نادیدنی‌ها و عمق را می‌بینند \nدود خورده این مکتب هستند، نمی‌توانند عظمت الهی و به حقیقت خدای متعال دست پیدا کنند","بخش دوم:\n\nمتن:\nالَّذِی لَیسَ لِصِفَتِهِ حَدٌّ مَحْدُودٌ وَ لَا نَعْتٌ مَوْجُودٌ وَ لَا وَقْتٌ مَعْدُودٌ وَ لَا أَجَلٌ مَمْدُودٌ فَطَرَ الْخَلَائِقَ بِقُدْرَتِهِ وَ نَشَرَ الرِّیاحَ بِرَحْمَتِهِ وَ وَتَّدَ بِالصُّخُورِ مَیدَانَ أَرْضِهِ.\nأَوَّلُ الدِّینِ مَعْرِفَتُهُ وَ کمَالُ مَعْرِفَتِهِ التَّصْدِیقُ بِهِ وَ کمَالُ التَّصْدِیقِ بِهِ تَوْحِیدُهُ وَ کمَالُ تَوْحِیدِهِ الْإِخْلَاصُ لَهُ وَ کمَالُ الْإِخْلَاصِ لَهُ نَفْی الصِّفَاتِ عَنْهُ لِشَهَادَةِ کلِّ صِفَةٍ أَنَّهَا غَیرُ الْمَوْصُوفِ وَ شَهَادَةِ کلِّ مَوْصُوفٍ أَنَّهُ غَیرُ الصِّفَةِ، فَمَنْ وَصَفَ اللَّهَ سُبْحَانَهُ فَقَدْ قَرَنَهُ وَ مَنْ قَرَنَهُ فَقَدْ ثَنَّاهُ وَ مَنْ ثَنَّاهُ فَقَدْ جَزَّأَهُ وَ مَنْ جَزَّأَهُ فَقَدْ جَهِلَهُ وَ مَنْ جَهِلَهُ فَقَدْ أَشَارَ إِلَیهِ وَ مَنْ أَشَارَ إِلَیهِ فَقَدْ حَدَّهُ وَ مَنْ حَدَّهُ فَقَدْ عَدَّهُ.\n\nترجمه:\nهمان کسی که برای صفاتش حدّی نیست و توصیفی برای بیان اوصافش وجود ندارد و نه وقت معینی و نه سرآمد مشخّصی برای ذات پاک اوست. مخلوقات را با قدرتش آفرید و بادها را با رحمتش به حرکت درآورد و گسترش داد و لرزش و اضطراب زمین را به‌وسیله کوه‌ها آرام ساخت.\nسرآغاز دین، معرفت و شناخت اوست و کمال معرفتش تصدیق به ذات پاک اوست و کمال تصدیق به او همان توحید اوست و کمال توحیدش، اخلاص برای اوست و کمال اخلاص برای او، نفی صفات ممکنات از اوست. چرا که هر صفتی (از این صفات) گواهی می‌دهد که غیر از موصوف است و هر موصوفی (از ممکنات) شهادت می‌دهد که غیر از صفت است، پس هر کس خداوند سبحان را (با صفاتی همچون صفات مخلوقات) توصیف کند او را با امور دیگری قرین ساخته و آن کس که او را با چیز دیگری قرین کند دوگانگی در ذات او قائل شده و کسی که دوگانگی برای او قائل شود اجزایی برای او پنداشته و هر کس برای او اجزایی قائل شود به‌راستی او را نشناخته است و کسی که او را نشناسد به او اشاره می‌کند و هر کس به او اشاره کند او را محدود شمرده و هر کس او را محدود بداند او را به شمارش درآورده است (و در وادی شرک سرگردان شده است)!\n\nتفسیر:\nفرمود: نه از جهت عمل می‌توانید حمد و سپاس خدا را بجا آورید و نه در مقام فهم و درک هستید\nفهم انسان بسیار کوچک است بتواند به حد اعلای شکر و حمد برسد\n\n💠الَّذِی لَیسَ لِصِفَتِهِ حَدٌّ مَحْدُودٌ \nحمد مختص خدایی که برای صفات او حدی نیست\nاینکه صفات خدا، قدرت، علم، عظمت خدا در چه حد است \n نمی‌توان اندازه‌گیری کرد\n\n💠وَ لَا نَعْتٌ مَوْجُودٌ \nنعت = توصیف \nنه خود صفات محدودی دارد و نه توصیف‌کردن صفات ممکن است\nخود صفات هم قابل‌فهم نیست؛ چون نامحدود است\nفهم وصف و توصیف صفات برای ما ممکن نیست\n\n💠وَ لَا وَقْتٌ مَعْدُودٌ \nبرای خدا وقت عددی و شمارش شده مطرح نیست\nآیا می‌توان به کنه خدایی دست‌یافت که ازلی است و عمر او قابل‌شمارش نیست\n سؤال در مورد، خدا «از کی» بوده معنا ندارد\n«از» برای خدا مطرح نیست همیشه بوده\n💠وَ لَا أَجَلٌ مَمْدُودٌ \nخدا نه ابتدایی دارد و نه اجلی و انتهایی\n و نه سرانجام او مشخص است\nبه دلیل این چهار صفت، هرچه تلاش شود به حد نهایی خدا رسیدن ممکن نیست\n۱. صفات نامحدود \n۲. ناممکن بودن وصف صفات\n۳. ابتدا در او راه ندارد\n۴. انتهای خدا معنا ندارد\nنه در عمل و نه در فهم نمی‌توان کنه ذات خدا را شناخت\n💠فَطَرَ الْخَلَائِقَ بِقُدْرَتِهِ \nمخلوقات را به قدرت خود خلق کرد\nفطر = شکافتن \nخدای قاطر عدم را شکافت و موجودات را پدید آورد بدون اینکه سابقهٔ قبلی داشته باشد\n💠وَ نَشَرَ الرِّیاحَ بِرَحْمَتِهِ \nحمد مختص خدایی که با رحمت، لطف و مهربانی باد را به حرکت آورد \nبادی که نماد رحمت است و وقت اجابت دعا. زیرا رحمت الهی به جوشش درآمده، \nمانند صلوات است که رحمت را به جوشش می‌آورد، موقعیتی است برای استجابت دعا\n– حرکت ابرها به سبب باد، \n- متراکم شدن ابرها به واسطه باد، \n- بارش به واسطه باد\n- جابه‌جایی هوای گرم و سرد \n- باد مانع از خفگی موجودات می‌شود\n💠وَ وَتَّدَ بِالصُّخُورِ مَیدَانَ أَرْضِهِ \nلرزش و اضطراب صفحات زمین را به سبب کوه‌ها آرام کرد\nهرکدام از کوه‌ها، سدی در مقابل ابرها، و به‌مثابه میخی در زمین، مانند ریشه یک درخت در اعماق زمین فرورفته، و از حرکت‌های صفحات زیر زمینی مانع شده زمین را آرام می‌کند\nعلاوه بر اینکه کوه‌ها یک نعمت معادن هم دارند\nبرای شناسایی و معرفی‌کردن خدا: \n💠أَوَّلُ الدِّینِ مَعْرِفَتُهُ \nهر دین و آیین و مرام حول محور الله می‌چرخد. هیچ ممکن نیست کسی دین‌دار باشد و در دین خدا را نشناسد و باخدا سروکار نداشته باشد. از عظمت و رحمت خدا خبر نداشته باشد\nاول دین معرفت است و این معرفت به معنای علامه شدن نیست تا خدا را بشناسد، بلکه خدا را باور کند که هست\nیک معرفت اجمالی خداباوری است\n💠وَ کمَالُ مَعْرِفَتِهِ التَّصْدِیقُ بِهِ \n کمال این معرفت اجمالی و خداباوری باید او را تصدیق کند\nشناخت خدا باید با تصدیق باشد\nتصدیق به چه معناست!! \nقولی:\nاین دو جمله [معرفت و تصدیق] اجمال و تفضیل را بیان می‌کند. \nهمه اجمالاً خدا را بشناسند، و کامل‌شدن آن قبول‌داشتن عظمت اوست.\nقولی:\nرابطه [معرفت و تصدیق] ، رابطهٔ فطرت و استدلال است. \nهمه فطرت خداشناسی داریم و این فطرت وقتی کارکرد درست پیدا می‌کند که استدلال درست داشته باشد. \nبا استدلال محکم عقیده ثابت می‌شود. \nاول دین معرفت است، بالاتر از آن دلیل و یقین است.\nدر حرف‌زدن قبول داریم خدا هست، اما در بحران شدید خدا فراموش می‌شود. گاهی خدا هیچ‌کاره می‌گردد و ابزارها و واسطه‌ها دستاویز می‌شود.\nخدا را قبول داریم؛ ولی یقین محکم نیست که همه‌کارهٔ عالم خداست. همه ابزار هم دست خداست او بخواهد مقدر کند همان می‌شود.\n💠وَ کمَالُ التَّصْدِیقِ بِهِ تَوْحِیدُهُ \nبالاترین مرتبه‌ی تصدیق آن است که موحد باشیم . \nکمال اعتقاد به خدا، در تمام امور موحد بودن است. \nدر روایات: کمترین مرتبه شرک آن است که گفته شود، اول خدا دوم فلان‌کس . \nاین شرک است. \nدرحالی‌که اول خدا، وسط خدا، آخر هم خدا و همه‌کاره خداست.\n💠وَ کمَالُ تَوْحِیدِهِ الْإِخْلَاصُ لَهُ \nکمال توحید آن است که توحید ناب باشد. توحید خالص باشد. \nمعنای اخلاص آنی که در ذهن ما هست، نیست. برای ریا نیست. \nاخلاص بدون هیچ‌گونه ناخالصی.\n💠وَ کمَالُ الْإِخْلَاصِ لَهُ نَفْی الصِّفَاتِ عَنْهُ\nبالاترین مرتبه خالص‌بودن توحید آن است که صفات را برای خدا قائل نشوید.\nنفی صفات از خدا: \nنفی صفات مخلوق است وگرنه قرآن و دعا پر است از صفات خداوند. با این کلام حضرت در تضاد نیست.\nتوحید خالص، یعنی خداوند هیچ‌کدام از صفت مخلوق را ندارد. \n هر یک از صفات مخلوق حدی و ضعفی دارد. \nصفات انسان محدود است، اما صفات خداوند در عالی‌ترین درجه وجود دارد.\nعلم انسان اکتسابی است . \nاما علم خدا، وجود خدا علم است، وجود خدا قدرت، وجود خدابخشش است.\nهر دانشمندی با هر تخصصی دچار فراموشی می‌شود. ما غیر از صفات خود هستیم. \nصفتی بنام علم داریم که در کودکی نبود در جوانی کسب شد، در پیری از دست می‌رود. \nاما علم خدا گذشته و حال و آینده همیشگی عالم است و علم او درونی و از خود اوست.\n\n💠 فَمَنْ وَصَفَ اللَّهَ سُبْحَانَهُ فَقَدْ قَرَنَهُ وَ مَنْ قَرَنَهُ فَقَدْ ثَنَّاهُ\nکسی خدا را به صفات انسان‌ها توصیف کند، خدا را با جسم و صفت ناقص یکی کرده است.\nاگر کسی خدا را با صفات کوچک گره بزند و یکی کند دوگانگی برای خدا ایجاد کرده.\n💠وَ مَنْ ثَنَّاهُ فَقَدْ جَزَّأَهُ\nکسی که خدا را دوگانه کرده او را تجزیه کرده.\nانسان چه از نظر جسم، چه روح از اجزایی تشکیل شده. چشم و گوش، دست‌وپا، و در صورت نقص جسم در جای خود سالم است یک عضو چشم کور شده.\nروح ما هم متشکل از اجزای مختلف است \nاما خدا این‌گونه نیست. خدا مرکب از اجزا نیست. \nدایره‌ای نیست که قسمتی از آن جود باشد قسمی علم و قسمی حلم باشد. \nخدا دارای صفات است همه صفات از وجود اوست، وجود او همه علم است و همه وجود قدرت است.\n💠وَ مَنْ جَزَّأَهُ فَقَدْ جَهِلَهُ\nخدا بخش‌بخش نیست. اگر بخش شود احتیاج به وجود می‌آید، \nانسان محتاج به دست و زبان است. خدا به اجزا محتاج نیست\nخدا بسیط است. همه موجودات حتی ملائک مرکب‌اند. از چند جزء جسمی یا عقلی ترکیب شدند.\n💠وَ مَنْ جَهِلَهُ فَقَدْ أَشَارَ إِلَیهِ\nبرای خدا اجزا پنداشتن، در یک محدودهٔ خاص قرارگرفتن و محتاج بودن است. \n احتیاج را می‌شود اشاره کرد و اشاره نشانهٔ محدودیت است. \nهرکس محدود باشد خدا نیست. \nخدا را بشود اشاره کرد؛ یعنی محدود.\n💠 وَ مَنْ أَشَارَ إِلَیهِ فَقَدْ حَدَّهُ\nکسی را بشود اشاره کرد محدود است. \nهوا را نمی‌توان اشاره کرد همه‌جا هست. \nاما درخت را با انگشت می‌توان دست کشید، چون حد دارد. محدود است قابل‌شمارش و اشاره است.\n💠وَ مَنْ حَدَّهُ فَقَدْ عَدَّهُ. \nو شیء محدود عدد دارد. \nقابل‌شمارش یعنی یک و دیگری هم مانند او هست. \nهم می‌شود «به این» اشاره کرد و هم «به آن» . \nدرحالی‌که خدا نامتناهی است و اشاره‌کردن معنا ندارد.\nلفظ نامتناهی انتها نداشتن است. \nذهن انسان همیشه با عدد، مقدار، متر، اینجا، آنجا، سروکار دارد. \nمی‌تواند با این محدودیت خدایی را تصور کند که انتها و محدودیت ندارد!!! \nعمر خدا «از کی» و «تا کی» معنا ندارد. \nانسان سرتاسر محدود و خدا سرتاسر نامحدود . \nآیا می‌تواند چنین خدایی را بشناسد!\nکنه ذات خدا برای هیچ‌کس حتی پیامبر قابل‌فهم نیست. \nما عرفناک حق معرفت \nنه اینکه کم‌کاری باشد، از حد فهم انسان به‌دور است. \nکنه ذات خدا برای پیامبر هم قابل‌شناخت نیست. \nصفات و افعال خدا باید شناسایی شود. \nرابطه‌ی حکمت و رحمت چیست را می‌توان شناخت. اما علم و حیات خدا از خود اوست یعنی چه!! \n قابل‌فهم و شناخت نیست.","بخش سوم:\n\nمتن:\n وَ مَنْ قَالَ فِیمَ فَقَدْ ضَمَّنَهُ وَ مَنْ قَالَ عَلَامَ فَقَدْ أَخْلَی مِنْهُ. کائِنٌ لَا عَنْ حَدَثٍ مَوْجُودٌ لَا عَنْ عَدَمٍ مَعَ کلِّ شَیءٍ لَا بِمُقَارَنَةٍ وَ غَیرُ کلِّ شَیءٍ لَا بِمُزَایلَةٍ، فَاعِلٌ لَا بِمَعْنَی الْحَرَکاتِ وَ الْآلَةِ بَصِیرٌ إذْ لَا مَنْظُورَ إِلَیهِ مِنْ خَلْقِهِ، مُتَوَحِّدٌ إذْ لَا سَکنَ یسْتَأْنِسُ بِهِ وَ لَا یسْتَوْحِشُ لِفَقْدِهِ.\nأَنْشَأَ الْخَلْقَ إِنْشَاءً وَ ابْتَدَأَهُ ابْتِدَاءً بِلَا رَوِیةٍ أَجَالَهَا وَ لَا تَجْرِبَةٍ اسْتَفَادَهَا وَ لَا حَرَکةٍ أَحْدَثَهَا وَ لَا هَمَامَةِ نَفْسٍ اضْطَرَبَ فِیهَا أَحَالَ الْأَشْیاءَ لِأَوْقَاتِهَا وَ [لَاءَمَ] لَأَمَ بَینَ مُخْتَلِفَاتِهَا وَ غَرَّزَ غَرَائِزَهَا وَ أَلْزَمَهَا أَشْبَاحَهَا عَالِماً بِهَا قَبْلَ ابْتِدَائِهَا مُحِیطاً بِحُدُودِهَا وَ انْتِهَائِهَا عَارِفاً بِقَرَائِنِهَا وَ أَحْنَائِهَا.\n\nترجمه:\nو هر کس بگوید خدا در چیست؟ او را در ضمن چیزی پنداشته و هر کس بپرسد بر روی چه قرار دارد؟ جایی را از او خالی دانسته.\nهمواره بوده است و از چیزی به وجود نیامده. وجودی است که سابقه عدم برای او نیست. با همه چیز همراه است، امّا نه این که قرین آن باشد و با همه چیز مغایر است، امّا نه این که از آن بیگانه و جدا باشد. \nاو انجام‌دهنده (هر کاری) است، امّا نه به آن معنا که حرکات و ابزاری داشته باشد.\nبیناست حتّی در آن زمانی که موجود قابل رؤیتی از خلقش وجود نداشته است. یگانه و تنهاست زیرا کسی نیست که با او انس گیرد و از فقدانش ناراحت و متوحّش شود.\n\nآفرینش را بدون نیاز به اندیشه و فکر و استفاده از تجربه و بی آن که حرکتی ایجاد کند و درباره تصمیمی بیندیشد ایجاد کرد و آغاز نمود. خلقت هر موجودی را به‌وقت خاصّش موکول کرد موجودات گوناگون را با یکدیگر التیام داد و به هر کدام طبیعتی مخصوص و غریزه‌ای ویژه بخشید و صفات ویژه آنها را همراهشان ساخت و پیش از آن که آنها را بیافریند از همه آنها آگاه بود و به حدود و پایان آنها احاطه داشت و از جمیع لوازم و تمام جوانب آنها باخبر بود.\n\nتفسیر:\n💠وَ مَنْ قَالَ فِیمَ فَقَدْ ضَمَّنَهُ\nاگر کسی بگوید خدا در چیزی قرار دارد!! \nخدا را در ضمن چیزی قرار داده.\nخدا را داخل در چیزی بداند، یعنی خدا را در درون خانه بداند، خانه بر خدا محیط است. درحالی‌که چیزی بر خدا احاطه ندارد. \n💠وَ مَنْ قَالَ عَلَامَ فَقَدْ أَخْلَی مِنْهُ\nاگر کسی بگوید خدا بر روی چیزی قرار دارد!! \nخدا روی چیزی قرار داشته باشد؛ یعنی درون آن نیست. \nبر روی عرش باشد؛ یعنی در زمین نیست.\nخدا را در قالب جسم بدانیم؛ مانند خود محدودکردن است. محدودکردن باخدا سازگاری ندارد.\nآنچه در ذهن انسان از خدا ساخته می‌شود، ساخته ذهن خود را پرستش می‌کند. \nآنچه برای خدا تصور کنید حتی نور شدید، آن مخلوق ذهن بشر است، نمی‌تواند خالق باشد. تصورکردن بر خدا معنا ندارد.\n«الرحمنُ علیَ العرشِ استَویٰ» اهل‌سنت قائل است خدا بر روی عرش است. برای خدا جسم مجسم کردن است. \n امامیه خدا را مبرا از جسم می‌داند. \n «علی العرش» بودن معنای حقیقی ندارد، بلکه کنایی است. \n «علی العرش» نشانۀ احاطه است. \nعرش مرکز فرماندهی عالم است، مانند سر که جایگاه فرماندهی بدن را دارد. \nدر نظام عالم عرش جایگاه مهم دارد. \nاحاطهٔ صددرصد بر عرش یعنی احاطهٔ صددرصد بر تمام عالم، ولی به معنای ایستادن بر عرش نیست. چون جسم تلقی می‌شود. \nو از آسمان‌های دیگر و زمین بی‌خبر می‌ماند.\n💠کائِنٌ لَا عَنْ حَدَثٍ\nخدا همیشه بوده؛ اما این‌گونه نیست که قبلاً نبوده و بعد به وجود آمده باشد [حدث]\nهمیشه بودن خدا «از» زمانی به وجود آمده باشد نیست.\nانسان است که سال، ماه، روزی نبوده بعد پدیدآمده. \nسال، روز، هفته، از چرخش شمس و قمر پدیدآمده، خدا خالق آنهاست، خالق هرگز نمی‌تواند ذیل مخلوق خود قرار بگیرد.\nخدا همواره بوده؛ ولی بودن او به نحو ایجادشدن نیست. \nحیات ذات خداوند است بدون اینکه به وجود آید.\n💠مَوْجُودٌ لَا عَنْ عَدَمٍ\nخدا وجود دارد؛ ولی وجود او مسبوق به عدم نیست. \nانسان سابقهٔ نبود و عدم دارد. بعد از تاریخی به وجود آمده. \nخدا هست؛ ولی سابقه نبود و نیستی در او راه ندارد.\n💠مَعَ کلِّ شَیءٍ لَا بِمُقَارَنَةٍ\nخدا با همه چیز هست \nبا تک‌تک اشیا عالم همراه است، ولی همراهی خدا مقارنت و یکی‌شدن نیست.\n» هو معَکم آبنما کنتُم» به این معنا نیست که خدا جزئی از شماست . \nبا شما هست؛ ولی قرین، چسبیدن با شما، و مثل شما نیست.\n💠وَ غَیرُ کلِّ شَیءٍ لَا بِمُزَایلَةٍ\nخدا از همه چیز جدا هست؛ ولی جدایی خدا دوگانگی و دوئیت نیست [مزابله]\n این‌طور نیست که ارتباط نداشته باشد.\nخدا با ما هست؛ چون لطف، عنایت او با ما هست. لحظه‌ای عنایت او با ما نباشد، هیچ و عدم می‌شویم. \nخدا با ما نیست، چون شأن و جایگاه خالق و مخلوق چه رابطه‌ای می‌تواند با هم داشته باشد!\nازیک‌طرف تباین کلی برقرار است، صددرصد اختلاف داریم، او خالق است و ما مخلوق.\nاز جهت دیگر ارتباط تنگاتنگ داریم؛ چون ما از منبع نور است که نور می‌گیریم. \nمانند یک شعاع خورشید که هرگز خود را جدای از خورشید و مستقل نمی‌داند. لحظه‌ای خورشید نور قطع کند از شعاع چیزی باقی نمی‌ماند.\nخدا لحظه‌به‌لحظه بما توان، قدرت، حیات می‌دهد ما هستیم آنی قطع کندکار ما تمام است. \nخدا با ما معیت دارد؛ اما به این نحو نیست که شبیه ما باشد و قدم‌به‌قدم با ما بیاید.\n \nافعال خداوند: \n💠فَاعِلٌ لَا بِمَعْنَی الْحَرَکاتِ وَ الْآلَةِ\nفعل خدا به معنای حرکت نیست، هم حرکت جسمانی و هم حرکت فکری. \nدر حرکت جسمی ما آجر به آجر حرکت داریم تا دیوار ساخته شود. \nدر حرکت فکر یعنی معادله‌ای که بین معلوم و مجهول دائم حرکت ردوبدل باشد تا معادله حل شود.\nخدا کاری انجام می‌دهد به معنای حرکت نیست. \nخدا با ابزار و اسباب کار نمی‌کند، اراده کندکار انجام می‌شود.\nملائکی که مدبران امر هستند و کارها به سبب آنها انجام می‌شود. \nچون خدا اراده کرده عالم از طریق اسباب اداره شود. یکی مسئول باران، یکی مسئول باد، و…\nباشد. اما خدا به آنها محتاج نیست!!! \nکه بدون آن اسباب و مسئول باران بارش باران لنگ بماند \nبدون احتیاج به آنها انواع معجزات بااراده خدا صورت‌گرفته. \nآتش باخاصیت سوزانندگی سرد می‌شود. \nکوه تبدیل به شتر صالح می‌گردد. \nقدرت خداوند بر همه اسباب قاهر و غلبه دارد. \nقدرت دارد از حالت طبیعی خارج کند.\nانسان برای خلق به قبلی خود نگاه می‌کند تا تجربه کسب کند. \nیا در ابداع تفکر، محاسبه، با ساختن و خراب‌شدن تا به نتیجه برسد. \nخدا برای خلق عالم تجربه، فکر، محاسبه نمی‌کند، شکست نمی‌خورد تا دوباره بهتر بسازد. \nبرای خلق اندیشه نکرد فاصله خورشید از زمین و ماه محاسبه نکرد که در مدار بیضوی شکل با چه سرعتی حرکت کند.\n💠بَصِیرٌ إذْ لَا مَنْظُورَ إِلَیهِ مِنْ خَلْقِهِ\nمنظور = کسی که نظر می‌کند\nخدا بیناست، احاطه دارد زمانی که مخلوقی نبود که خدا نگاه کند. \nبینایی و علم خداوند بعد از خلق مخلوقات به دست نیاورده. \nکسی نبود تا خدا رزق بدهد؛ ولی رزاق بود. \nاگر چنین باشد که بعد از خلقت بصیر شود یک ضعف است و خدا نقصی در او راه ندارد. \nهمه صفات خدا بود بعد از خلقت نمود پیدا کرد.\n💠مُتَوَحِّدٌ إذْ لَا سَکنَ یسْتَأْنِسُ بِهِ وَ لَا یسْتَوْحِشُ لِفَقْدِهِ\nخدا یگانه بود قبل از آنکه کسی باشد که خدا بخواهد با او مأنوس باشد. \n این‌گونه نبود که از فقدان و نبود او، به خدا وحشت راه پیدا کند.\n \nانشاء خلق: \n💠أَنْشَأَ الْخَلْقَ إِنْشَاءً وَ ابْتَدَأَهُ ابْتِدَاءً\nخدا خواست عالم را خلق کند [انشا] \nابتدائاً ایجاد کرد بدون الگو و ماکت قبلی. \nعالمی مشخص نبود که الگویی باشد. \nلذا خلق عالم ابتدایی است. \n [تفاوت عمده‌ی انسان باخدا در همین است، نیاز به تفکر، حرکت، اضطراب نیست و سرانجام شکست یا….] \n💠بِلَا رَوِیةٍ أَجَالَهَا وَ لَا تَجْرِبَةٍ اسْتَفَادَهَا \nعالم را خلق کرد بدون تفکر و عادت [لا رویه]\nخلق کرد بدون جوَلان راه، بدون اینکه مهندسی کند [اجلیٰ]\nفکر و عقل یک ابزار خوبی است هر کس استفاده کند موفق است؛ اما همین عقل و فکر به خدا نسبت‌دادن اشتباه است. \nاندیشه و مغز و فکر برای خدا معنا ندارد، چون محدود می‌کند. \n تمام وجود خدا علم است نیاز به فکر ندارد. \nخلقت عالم بدون تجربه خود و دیگران ایجاد شد.\n💠وَ لَا حَرَکةٍ أَحْدَثَهَا\nبدون حرکت خلق کرد . \nحرکت برای انسان است، مرحله‌به‌مرحله کار پیش ببرد تا چیزی پدید آید.\n💠وَ لَا هَمَامَةِ نَفْسٍ اضْطَرَبَ فِیهَا\nخلق عالم بدون شک‌وتردید بود که او را به اضطراب بیندازد. \nآیا درست انجام گرفت! \nنوع آن خوب بود! \nتعداد به مقدار لازم بود! \nدچار تردید نشد که مساوی با اضطراب باشد.\nنکته اخلاقی: \n علت تنش درونی، خانوادگی، اجتماعی از دودلی و تردید است . وقتی از عمق جان به چیزی یقین نباشد اضطراب وارد می‌شود. \nیقین که باشد در کانون مشکلات و ناآرامی آرام است. دست‌بردار نیست حتی تنها در وسط دشمن باشد. با یقین است که به ثبوت می‌رسد. \nیقین نباشد در هر امری با کوچک‌ترین تردید و شک فی‌الفور دست می‌کشد.\n \n 💠أَحَالَ الْأَشْیاءَ لِأَوْقَاتِهَا \nخدا در وقت خاص خود هر کاری را به وجود می‌آورد. \nیک انسان حکیم کار خود را به تأخیر و تنبلی واگذار نمی‌کند در زمان معین و خاص خودکار را به ثمر می‌رساند.\nخدا برای کسی عجله نمی‌کند به تعویق هم نمی‌اندازد. با التماس کسی هم حکمت خود را زیر سؤال نمی‌برد. \nهر چیزی در زمان خاص خود انجام می‌شود.\n💠وَ [لَاءَمَ] لَأَمَ بَینَ مُخْتَلِفَاتِهَا\nخدا در خلقت عالم‌بین امور مختلف الفت ایجاد کرد. بین آب‌وآتش، بین بادوخاک، بین کود بدبو و پذیرش درخت، با هم الفت دارند. یکدیگر را راحت می‌پذیرند.\n💠وَ غَرَّزَ غَرَائِزَهَا\nدر انسان غریزه قرارداد که همان فطرت است\n «فطرت الله کلید دگرسازی فطرَ الناسَ علی‌ها» \nدر غیرانسان غریزه قرارداد. \nهیچ موجودی نیست که لوح نانوشته داشته باشد. \nهرکدام از اشیای عالم غریزه‌ای دارد. [یک غریزه عمومی مانند دفاع از خود، خواب، گرسنگی]\n💠وَ أَلْزَمَهَا أَشْبَاحَهَا\nخدا ملزم کرد با هر کدام از اشیا غریزه خاص به خود را. \nبه خرچنگ ابزار موردنیاز حیات خود را داد. \nپرندگان بر قلل کوه‌ها ابزار و غرایز موردنیاز. \nماهی در اعماق دریای بدون نور غریزه متناسب با حیات او داد. \nیک غریزه عمومی داد و یک غریزه خاص متناسب با هر موجودی،\n💠عَالِماً بِهَا قَبْلَ ابْتِدَائِهَا مُحِیطاً بِحُدُودِهَا وَ انْتِهَائِهَا\nبه همه موجودات قبل از خلق آنها علم داشت. \nاز ابتدا تا انتهای هر مخلوقی علم دارد.\nعلم انسان این‌گونه است که باید صحنه را تماشا کند تا اطلاعات به دست آورد. \nعلم خدا حضور در صحنه نیست. \nقبل از خلق آدم، می‌داند آدمی خلق می‌شود با چند فرزند دختر و پسر، زندگی در کجا، مرگ چه زمان و با چه عمری، انتهای امر او بهشت است یا دوزخ. \n تماشای صحنه لازم ندارد. \nبه حد و حدود همه اشیا محیط است. \nو به تمام لوازم [قرائن]  و اطراف [اَحنا] آگاه است.","بخش چهارم: \n\nمتن:\nثُمَّ أَنْشَأَ سُبْحَانَهُ فَتْقَ الْأَجْوَاءِ وَ شَقَّ الْأَرْجَاءِ وَ سَکائِک الْهَوَاءِ فَأَجْرَی فِیهَا مَاءً مُتَلَاطِماً تَیارُهُ مُتَرَاکماً زَخَّارُهُ حَمَلَهُ عَلَی مَتْنِ الرِّیحِ الْعَاصِفَةِ وَ الزَّعْزَعِ الْقَاصِفَةِ فَأَمَرَهَا بِرَدِّهِ وَ سَلَّطَهَا عَلَی شَدِّهِ وَ قَرَنَهَا إِلَی حَدِّهِ الْهَوَاءُ مِنْ تَحْتِهَا فَتِیقٌ وَ الْمَاءُ مِنْ فَوْقِهَا دَفِیقٌ ثُمَّ أَنْشَأَ سُبْحَانَهُ رِیحاً اعْتَقَمَ مَهَبَّهَا وَ أَدَامَ مُرَبَّهَا وَ أَعْصَفَ مَجْرَاهَا وَ أَبْعَدَ مَنْشَأَهَا فَأَمَرَهَا بِتَصْفِیقِ الْمَاءِ الزَّخَّارِ وَ إِثَارَةِ مَوْجِ الْبِحَارِ فَمَخَضَتْهُ مَخْضَ السِّقَاءِ وَ عَصَفَتْ بِهِ عَصْفَهَا بِالْفَضَاءِ تَرُدُّ أَوَّلَهُ [عَلَی] إِلَی آخِرِهِ وَ سَاجِیهُ [عَلَی] إِلَی مَائِرِهِ حَتَّی عَبَّ عُبَابُهُ وَ رَمَی بِالزَّبَدِ رُکامُهُ فَرَفَعَهُ فِی هَوَاءٍ مُنْفَتِقٍ وَ جَوٍّ مُنْفَهِقٍ فَسَوَّی مِنْهُ سَبْعَ سَمَوَاتٍ جَعَلَ سُفْلَاهُنَّ مَوْجاً مَکفُوفاً وَ عُلْیاهُنَّ سَقْفاً مَحْفُوظاً وَ سَمْکاً مَرْفُوعاً بِغَیرِ عَمَدٍ یدْعَمُهَا وَ لَا دِسَارٍ [ینْتَظِمُهَا] ینْظِمُهَا ثُمَّ زَینَهَا بِزِینَةِ الْکوَاکبِ وَ ضِیاءِ الثَّوَاقِبِ وَ أَجْرَی فِیهَا سِراجاً مُسْتَطِیراً وَ قَمَراً مُنِیراً فِی فَلَک دَائِرٍ وَ سَقْفٍ سَائِرٍ وَ رَقِیمٍ مَائِرٍ.\n\nترجمه:\nسپس خداوند سبحان طبقات جوّ را از هم گشود و اطراف آن را باز کرد و فضاهای خالی ایجاد نمود!\nسپس خداوند در آن (فضای عظیم) آبی جاری ساخت که امواج متلاطم و متراکم داشت و آن را بر پشت تندبادی شدید و طوفانی کوبنده و شکننده سوار کرد. سپس باد را به بازگرداندن آن امواج فرمان داد و بر نگهداری‌اش مسلّط ساخت و تاحدی‌که لازم بود، آن دو را با هم مقرون ساخت، فضای خالی در زیر آن گشوده شده بود و آب در بالای آن در حرکت سریع قرار داشت.\nسپس خداوند پاک و منزّه، طوفانی برانگیخت که کار آن متلاطم ساختن آب و درهم‌کوبیدن امواج بود، طوفان به‌شدت می‌وزید و از نقطه‌ای دور، سرچشمه می‌گرفت. پس به آن فرمان داد که آب‌های متراکم را بر هم زند و امواج دریاها را به هر سو بفرستد! در نتیجه، همچون مشک سقّایی آنها را به هم زد و با همان شدّت که در فضا می‌وزید، به آن امواج حمله‌ور شد. آغازش را بر آخرش فرومی‌ریخت و قسمت‌های ساکن آن را به امواج متحرّک پیوند می‌داد. تا آب‌ها روی‌هم انباشته شد و همچون قلّه کوه بالا آمد و امواج، کف‌هایی را بیرون فرستاد و در هوای باز و جوّی وسیع، پراکنده ساخت و از آن هفت‌آسمان را پدید آورد.\nآسمان پایین را همچون موج مهار شده‌ای قرار داد و آسمان برترین را همچون سقفی محفوظ و بلند. بی آن که ستونی برای نگاهداری آن باشد و نه میخ‌هایی که آن را ببندد. سپس آسمان پایین را به‌وسیله کواکب و نور ستارگان درخشنده زینت بخشید و چراغی روشنی‌بخش و ماهی نورافشان در آن به جریان انداخت، در مداری متحرّک و سقفی گردان و صفحه‌ای جنبده.\n\nتفسیر:\nخلقت آسمان\n💠ثُمَّ أَنْشَأَ سُبْحَانَهُ فَتْقَ الْأَجْوَاءِ وَ شَقَّ الْأَرْجَاءِ\nخدای سبحان ایجاد کرد فضا را. \nیک جوی را خلق کرد و گسترش دارد. \nاطراف‌واکناف [ارجاء] فضا را هم شکافی ایجاد کرد. \nمانند بادکنکی که از سه چهار طرف محفظه‌ای و سوراخی ایجاد شود.\n💠 وَ سَکائِک الْهَوَاءِ\nبالای جو یک‌هوای دیگری درست کرد. \nیعنی طبقه به طبقه، \nاستنشاق هوا، هوا به معنای سقوط و افتادن است. \nمانند هوای نفس انسان را سقوط معنوی می‌دهد.\n💠 فَأَجْرَی فِیهَا مَاءً مُتَلَاطِماً تَیارُهُ\nجاری کرد در این فضای گسترده، آب متلاطم و پر موجی را که موج بر روی موج می‌زد.\nبعد از فضای کلی، ماده ابتدایی و اصلی عالم را آب بیان می‌فرماید.\n💠 مُتَرَاکماً زَخَّارُهُ\nآب‌ها پشت‌به‌پشت بر روی‌هم مرتفع [زخاره]\nموج‌های آب بالا می‌رود. با ارتفاع بالا دوباره بر روی آب می‌افتد\n💠 حَمَلَهُ عَلَی مَتْنِ الرِّیحِ الْعَاصِفَةِ\nبعد از جوشش آب یک تندباد به سمت آب فرستاد. \nیک تندباد سریع‌السیر، به آب در حال خروش حمله‌ور شد.\nتصور صحنهٔ آبی که عظمت آن برای ما معلوم نیست. این آب در فضا قرار گرفته ظرفی می‌خواهد که آب درون آن باشد، مگر می‌شود آب در هوا باشد!!! \nهمان باد و هوای اولی که حضرت فرمود در واقع یک ظرفی شد برای آب. \nکه اجازه نمی‌دهد قطرات آب پایین آید معلق نگه می‌دارد.\nیک باد شدید این آب را نگه می‌دارد، هوا و تندباد شدید از بالا بر آب می‌زند و مدام او را به حرکت می‌آورد [متلاطِماً تیّاره]\n💠 وَ الزَّعْزَعِ الْقَاصِفَةِ\n یک باد پر حرکت [زَعزع]  و شکننده بر آب حمله می‌کند.\n💠 فَأَمَرَهَا بِرَدِّهِ\nوظیفه این باد این است: که آب را در جای خود نگه دارد. \nدر واقع موج آب را بالا می‌برد ممکن است آب پخش شود بر جای خود نماند. باد را مأمور کرد دورتادور این دریای عظیم به سمت مرکزی بوزد تا آب سر جای خود بماند.\n💠 وَ سَلَّطَهَا عَلَی شَدِّهِ\nباد را بر نگهداری آب مسلط کرد. \nباد راه محکم بر سر آب ببندد تا آب به هرز نرود.\n💠 وَ قَرَنَهَا إِلَی حَدِّهِ\nمحدود کرد آب را به حدود خود که از حد خود تجاوز نکند.\nاین چند جمله و الفاظ شاید معنای واحدی داشته باشد و تفاوت‌های آنها معلوم نباشد. \nاما هر حرف و هر جمله در ظاهر شبیه به هم اما یک معنای جدیدی دارد و حضرت لفاظی نکرده و فقط جملات را طولانی کرده باشد.\n💠 الْهَوَاءُ مِنْ تَحْتِهَا فَتِیقٌ وَ الْمَاءُ مِنْ فَوْقِهَا دَفِیقٌ\nدر زیر آب فضای خالی بزرگی قرار دارد. \nفضایی که آب در آن قرار گرفت و باد از زیر آن می‌وزید.\n💠 ثُمَّ أَنْشَأَ سُبْحَانَهُ رِیحاً اعْتَقَمَ مَهَبَّهَا\nخداوند یک باد دومی خلق کرد که عقیم بود [اعتقم]\nمعلوم است بعضی از بادها عقیم نیستند، بارور می‌کنند. شاید بادی که می‌وزد گرده‌افشانی می‌کند و لقاح صورت می‌گیرد آیا منظور این باد است یا نه!! \nبر ما معلوم نیست. \nیا واقعاً باد خود موجودی است و حقیقتی دارد عقیم دارد و غیر عقیم. \nدقیق معنا و مفهوم آن بر ما واضح نیست.\n💠 مَهَبَّهَا وَ أَدَامَ مُرَبَّهَا\nباد به هیجان [مهبها] می‌آورد و ابر را بالا و پایین می‌برد. با مداومت و همیشگی.\nخدا باد را درحالی‌که شدید بود و از شدت آن هم کم نمی‌شد. \nباد همین‌طور با شدت و حدت مدام می‌وزید. \nتندباد چنددقیقه‌ای نبود که آرام بگیرد.\nزمانی که طوفان به دریا می‌وزد آب سطح دریا را موج می‌دهد به اعماق دریا نفوذ نمی‌کند، قدرت تندباد در سطح دریا ست اعماق آب آرام هستند.\nتصویر حضرت از این باد چنان شدید است که آب زیرورو می‌شود. \nعظمت این آب هزاران برابر آب‌کرهٔ زمین است؛ ولی تندباد چنان قدرتی دارد که به عمق نفوذ کرده آب را بالا و پایین می‌برد. \n💠وَ أَبْعَدَ مَنْشَأَهَا\nمنشأ طوفان از کجا بود!! \nاز دوردست، فاصله منشأ باد و اینجا که عالم، در حال شکل‌گیری است، فاصله بسیار زیاد بود.\n💠فَأَمَرَهَا بِتَصْفِیقِ الْمَاءِ الزَّخَّارِ\nخدا به طوفان دستور داد آب‌های متراکم را به هم بکوبد. \nآب از داخل جوشش دارد و از بیرون تندباد آن را به خروش می‌آورد.\n💠وَ إِثَارَةِ مَوْجِ الْبِحَارِ\nامر شد امواج دریای پهناور را به هر طرف پرتاب کند.\n💠فَمَخَضَتْهُ مَخْضَ السِّقَاءِ وَ عَصَفَتْ بِهِ عَصْفَهَا\nآن‌قدر آب به هم خورد؛ مانند مشک زده شده [مخضته] که ناخالصی و کف‌هایی که روی آب قرار داشتند. زوائد از آب جدا شد.\nنور در هوا حرکت کند یک سرعت دارد، سرعت در فضا یک چیز است در آب حرکت کند چیز دیگری، سرعت کمتر می‌شود. \nمانند هواپیما در خلأ یک سرعت دارد در فضا سرعت دیگری، اجرام سرعت را می‌گیرد.\nاین باد هزاران کیلوگرم وزن را تحمل می‌کند، هیچ‌کدام از موانع سنگین نمی‌تواند جلوی سرعت او را بگیرد.\n💠 تَرُدُّ أَوَّلَهُ [عَلَی] إِلَی آخِرِهِ وَ سَاجِیهُ [عَلَی] إِلَی مَائِرِهِ\nآب چنان به هم می‌پیچد که اول آب روی آخر آن می‌افتد. \n آب زیرین دریا به حرکت می‌آید و آب رو به زیر دریا قرار می‌گرفت.\n💠 حَتَّی عَبَّ عُبَابُهُ\nآن‌قدر آب متراکم شد و آب روی آب انباشته شد.\n💠 وَ رَمَی بِالزَّبَدِ رُکامُهُ\nآب متلاطم کف کرد [زبَد] و به بالا پرتاب می‌شد.\n💠 فَرَفَعَهُ فِی هَوَاءٍ مُنْفَتِقٍ وَ جَوٍّ مُنْفَهِقٍ\nکفه‌های فضا را، بالا و پایین می‌کرد و در جو پخش می‌کرد. [منفهق] خود کف‌ها متراکم بودند.\nصحبت از کف، تصور کف‌های امروزی نشود. \nمواد مذاب، مواد اولیه کرات، کفی بود که پرتاب شد و در مدار کروی قرار گرفت. \nهفت‌آسمان از همان دریا به وجود آمد.\n💠فَسَوَّی مِنْهُ سَبْعَ سَمَوَاتٍ جَعَلَ سُفْلَاهُنَّ مَوْجاً مَکفُوفاً\nاز همین آب و کف آسمان ساخته شد. \n «کن‌فیکون» عالم باید طبق اسباب پیش برود، اسباب در هم بیامیزد و شرایط ممزوج شود تا شیء ای خلق شود. \nخدا محتاج اسباب نیست؛ ولی داب خدا از طریق اسباب پیش می‌رود.\nهفت‌آسمان شکل گرفت و آسمان پایین [سفلاهنّ] را به سبب امواج بست [مکفوف]\nموج‌ها مهار شد.\n💠وَ عُلْیاهُنَّ سَقْفاً مَحْفُوظاً\nآسمان هفتم را مانند سقف حفاظت شده روی شش آسمان قرار داد.\n💠وَ سَمْکاً مَرْفُوعاً\nآسمان بالا سقف بلندبالایی است.\n💠بِغَیرِ عَمَدٍ یدْعَمُهَا \nآسمان هفتم بلندبالا و مرفوع بدون ستون و معلق، خدا اراده کرد که بماند. \nاز بالا و پایین معلق است؛ اما اضطراب ندارد و لرزش احساس نمی‌شود. آرام است.\n 💠وَ لَا دِسَارٍ ینْظِمُهَا \nمرفوع قرار دارد؛ ولی بر جایی میخکوب [دسار] نکرد. \nسرپا ایستاده، معلق، بدون ستون و بدون میخکوب‌شدن.\n 💠ثُمَّ زَینَهَا بِزِینَةِ الْکوَاکبِ وَ ضِیاءِ الثَّوَاقِبِ\nزینت‌دادن را اشاره می‌کند به پایین‌ترین آسمان  [سفلاهُنَ]\nزینت داد و آرایش کرد آسمان اول را به ستارگان پر نور و درخشنده.\n💠وَ أَجْرَی فِیهَا سِراجاً مُسْتَطِیراً وَ قَمَراً مُنِیراً\nجاری کرد ستارگان درخشان و ماه تابان را.\n💠فِی فَلَک دَائِرٍ\nتمام این آسمان و کرات در یک مداری متحرک‌اند. \nدر اصطلاح می‌گویند ساکن است. اما حرکت دارند . \nسیاراتی حرکت دارند؛ اما به‌قدری کند است در میلیون‌ها سال یک حرکت کند دارد. \nبرعکس زمین و ماه که مدام در حرکت‌اند. \nچون حرکت آنها نسبت به زمین بسیار کند است اصطلاحاً ساکن می‌گویند.\n💠وَ سَقْفٍ سَائِرٍ\nدر یک سقفی هستند که گردان است.\n💠وَ رَقِیمٍ مَائِرٍ\nهرکدام از ستاره‌ها در صفحه‌ای هستند.\n\nسیر خلقت آسمان و زمین: \n– ایجاد فضای بزرگ، مانند بوم نقاشی و ورقی منتخب برای نقاش که نقش خود را در آن فضا ایجاد کند.\n– ایجاد آب در حال جوش‌وخروش.\n– خلق تندباد که از زیر بوزد و حکم ظرف آب را داشته باشد.\n– ایجاد تندباد و وزیدن از بالا برای غلیان آب\nآیت‌الله مکارم با علم روز تطبیق داد.\n– تندباد اول می‌تواند قانون جاذبه باشد. \nجاذبه شیء را به سمتی خاص و مرکز هدایت می‌کند. \nآب‌های متراکم را از پراکندگی ممانعت می‌کند. \nآب‌ها به یک سمت در حرکت‌اند و مأمور آن را حضرت فرمود باد. \nبعید نیست منظور جاذبه زمین باشد.\n– تندباد دوم، کف درست کرد آب پخش کرد کف را بالا پرتاب کرد، همان نیروی گریزازمرکز بود. \nآب درون خود جوشید و چرخید و چرخید در حال حرکت، لحظه‌ای گریزازمرکز پیش آمد تا سیارات مختلف شکل گرفت. \nقطرات در جاهای مختلف پراکنده و پخش شد و نظام سپهر فعلی شکل گرفت.\n– بعید نیست آب در جوش‌وخروش همان انرژی هسته‌ای امروز باشد. \nخورشید به سبب انرژی هسته‌ای که دارد هسته اتم‌ها ترک برداشته، قدرت فراوانی دارد، گرما و حرارت دارد، و مدام در حال جوش‌وخروش است.\nآن زمان هم آتشی نبوده که آب اولیه خلقت در آتش بجوش آید. \nاز درون مواد آتش می‌گرفتند. در حرکت، به بالا و پایین پرتاب می‌شدند.\nایشان اظهار می‌دارد، اصرار نیست حتماً پذیرفته شود که کلمات حضرت منطبق با علم امروز بوده.\nالبته علم امروز در مورد پیدایش زمین همین موارد را بیان می‌کند. \nتودهٔ گازی با سرعت بسیار در حال چرخیدن به‌دور خود و از درون دارای انفجار، و قطعات توده عظیم گاز از هم جدا شده در فواصل مختلف قرار می‌گیرد. \nو در مرحله دوم سیارات کوچک با بزرگ ادغام و این فضای امروزی را به وجود می‌آورد.\nآیت‌الله مکارم: \nشاید هزاران سال بعد علم پیشرفت کرد و مطلب دیگری را اثبات کرد. \nاصل بر کلام امیرالمؤمنین است اگر علم به آن دست نیافته علوم نقص دارد. کلام حضرت اشتباه نیست.\nحضرت زمانی این مطالب را فرمود که نجوم و تلسکوپ نبود. طوری تصویر می‌کند و سخن می‌گوید گویا در زمان خلق عالم آنجا نشسته و نظاره می‌کرده و عیناً همه را دیده. \nعلی با قرآن و وحی سخن می‌گوید. به دوران ما نگاه نمی‌کند که علم چه می‌گوید. \nحرف، حرف علی است هزاران سال باید بگذرد تا علم ثابت کند، و بعید هم نیست که علم مادی اصلاً نتواند ثابت کند.\n\nنکته: \nماده اولیه خلق عالم را قرآن دخان معرفی می‌کند \nحضرت در اینجا آب! \nاین دو با هم در تعارض نیستند.\n– آب همان مواد مذاب یا گازهای فشرده بودند مثل بخار آب که از دور مانند آب است و از نزدیک به دود شبیه است.\nهرچه غلظت و سنگینی بیشتر باشد به آب بیشتر شبیه است و هرچه غلظت کمتر باشد به دود شبیه است. \nتضادی ندارد که ماده اولیه عالم گاز بوده که حقیقت آن بر ما معلوم نیست. \nآن گاز ظرفیت آن را داشته وقتی در یک شرایط دما و سرعت خاص قرار گرفته به سنگ، خاک، و اجرام تبدیل شده.\nروایات مختلف است اول خلق چه بوده؟ \n«اولُ ما خلق‌الله نوری» \n «اولُ ما خلق‌الله العقل» \nدر جملات حضرت اول خلق آب آمده. \nچطور می‌شود که چند چیز اول خلق باشد!! \nیک چیز تنها می‌تواند اول باشد!\nمرحوم فیض کاشانی: \nوقتی صحبت در اول خلق از نور پیامبر و عقل می‌شود صحبت از خلق مجردات است، \nدر خلق مجردات اول نور پیامبر بود، عقل هم همان پیامبر و عقل تام است.\nوقتی صحبت در عالم مادیات می‌شود، اول خلق آب است، توده آب و بخار شکل بوده \nنه اینکه منظور آب شرب امروزی باشد.\nسبع سموات: \nآسمان هفت‌گانه چیست و کجاست!!! \nدو نظر معروف وجود دارد. \nعلامه طباطبایی: از آسمان هفت‌گانه یک آسمان را می‌بینیم بقیه آسمان معنوی هستند. \nعرش، قرب، کرسی، هرکدام یک آسمان‌اند. \nجرم و جسم نیست آنان یک مقام‌اند. \nعیسی بن مریم به آسمان چندم رفت؛ یعنی مقام او در آن حد بود. \nو مقام پیامبر هم آن حد بود.\nقول دوم مکارم شیرازی: \nهیچ دلیلی نیست که آسمان هفت‌گانه معنوی باشد. \nآسمان اول جسم است، بقیه آسمان کجا هستند علم به آن نرسیده. \nهزاران سال نوری ستاره با ما فاصله دارد، تا وقتی از ستاره و زیبایی آن صحبت بوده، صحبت از آسمان اول است. هزاران سال نوری حرکت باشد هنوز در آسمان اول است. \nآسمان دوم و سوم از ستاره خبری نیست. \nآسمان‌های بعدی جرم و جسم هستند شاید علم بشر روزی به آن برسد. \nو اما الان آسمان کجاست خدا می‌داند.","بخش پنجم:\n\nمتن:\nثُمَّ فَتَقَ مَا بَینَ السَّمَوَاتِ الْعُلَا فَمَلَأَهُنَّ أَطْوَاراً مِنْ مَلَائِکتِهِ، مِنْهُمْ سُجُودٌ لَا یرْکعُونَ وَ رُکوعٌ لَا ینْتَصِبُونَ وَ صَافُّونَ لَا یتَزَایلُونَ\nوَ مُسَبِّحُونَ لا یسْأَمُونَ لَا یغْشَاهُمْ نَوْمُ الْعُیونِ وَ لَا سَهْوُ الْعُقُولِ وَ لَا فَتْرَةُ الْأَبْدَانِ وَ لَا غَفْلَةُ النِّسْیانِ، وَ مِنْهُمْ أُمَنَاءُ عَلَی وَحْیهِ وَ أَلْسِنَةٌ إِلَی رُسُلِهِ وَ مُخْتَلِفُونَ بِقَضَائِهِ وَ أَمْرِهِ، وَ مِنْهُمُ الْحَفَظَةُ لِعِبَادِهِ وَ السَّدَنَةُ لِأَبْوَابِ جِنَانِهِ، وَ مِنْهُمُ الثَّابِتَةُ فِی الْأَرَضِینَ السُّفْلَی أَقْدَامُهُمْ وَ الْمَارِقَةُ مِنَ السَّمَاءِ الْعُلْیا أَعْنَاقُهُمْ وَ الْخَارِجَةُ مِنَ الْأَقْطَارِ أَرْکانُهُمْ وَ الْمُنَاسِبَةُ لِقَوَائِمِ الْعَرْشِ أَکتَافُهُمْ نَاکسَةٌ دُونَهُ أَبْصَارُهُمْ مُتَلَفِّعُونَ تَحْتَهُ بِأَجْنِحَتِهِمْ مَضْرُوبَةٌ بَینَهُمْ وَ بَینَ مَنْ دُونَهُمْ حُجُبُ الْعِزَّةِ وَ أَسْتَارُ الْقُدْرَةِ لَا یتَوَهَّمُونَ رَبَّهُمْ بِالتَّصْوِیرِ وَ لَا یجْرُونَ عَلَیهِ صِفَاتِ الْمَصْنُوعِینَ وَ لَا یحُدُّونَهُ بِالْأَمَاکنِ وَ لَا یشِیرُونَ إِلَیهِ بِالنَّظَائِرِ.\n\nترجمه:\nسپس آسمان‌های بلند را از هم گشود و آنها را مملو از فرشتگان مختلف ساخت. گروهی از آنان همیشه در سجودند و رکوع ندارند و گروهی در رکوع‌اند و قیام نمی‌کنند و گروهی در صفوفی که هرگز از هم جدا نمی‌شود قرار دارند\n\nتفسیر:\n خلق ملائکه:\nانتهای قسمت آسمان‌ها: \nدو نقل درباره «رقیم مائر» وجود دارد\n ۱. آسمان و زمین یک صفحه نقاشی است.\n۲. آسمانی که شما می‌بینید نوشته‌ای در حال حرکت و گردش است اگر کسی به آسمان نگاه کند خیلی از مطالب را درمی‌یابد (این کلام اشاره به علم نجوم دارد) این علم نجوم در تغییر (مائر) است. \nبرای افراد در مکان‌های مختلف متغیر است. یکی از آیات قرآن «فنظر نظره فی النجوم فقال إنی سقیم» اشاره به همین علم نجوم داشتن حضرت ابراهیم است. این علوم چنان عظمت دارد که خداوند در قرآن به آن قسم می‌خورد\n «فلا أقسم بمواقع النجوم و إنه لقسم لو تعلمون عظیم» \n💠 ثُمَّ فَتَقَ مَا بَینَ السَّمَوَاتِ الْعُلَا\nفتق (جداکردن) در وهله اول هفت‌آسمان به‌هم‌چسبیده به وجود آورد بعد این آسمان‌ها را جدا کرد. \nدر وهله اول هفت‌آسمان به‌هم‌چسبیده؛ یعنی چه؟ \nمعلوم نیست ما ملتفت نمی‌شویم. \nآسمان‌های بالای را از یکدیگر جدا کرد.\n💠 فَمَلَأَهُنَّ أَطْوَاراً مِنْ مَلَائِکتِهِ\n مابین آسمان‌ها را از ملائکه گوناگون [اطوار] پر کرد. \nهیچ گوشه‌ای از آسمان‌ها را نمی‌بینی مگر ملایمی مستقر هستند که کار خود را انجام می‌دهند.\n\nاصناف مختلف ملائک: \n💠مِنْهُمْ سُجُودٌ لَا یرْکعُونَ\nمدام در سجده هستند و هیچگاه رکوع نمی‌کنند.\n💠وَ رُکوعٌ لَا ینْتَصِبُونَ\nملائکی مدام در حال رکوع هستند و هیچگاه قیام نمی‌کنند.\n💠وَ صَافُّونَ لَا یتَزَایلُونَ\nملائکی که در کنار هم صف‌کشیده‌اند و هیچ‌وقت از هم جدا نمی‌شوند. \nبه صف قد راست کرده‌اند. متفرق نمی‌شوند.\nگروه اول، ملایک عابد صفاتی دارند. \n ۱- مسبحون لا یسأمون\nعلی‌الدوام در حال تسبیح و خسته و ملول نمی‌شوند. بدون تنفس، استراحت، خواب عبادت می‌کنند.\nپیامبر: \nاهل آسمان اول تسبیح خاص، آسمان دوم تسبیح خاص دارند. \n «سبحان ذی الملک و الملکوت» \n۲- لا یغشاهم نوم العیون \n هیچگاه چشم آنها را خواب فرانمی‌گیرد.\n۳- و لا سهو العقول عقل\n ایشان دچار سهو و خطا نمی‌شود.\n۴- و لا فتره الابدان\n هیچگاه بدن‌هایشان دچار ضعف و سستی نمی‌شود.\n۵- و لا غفله النسیان هیچگاه فراموشی و نسیان بر آنها عارض نمی‌شود.\n یک استنباط: \nاگر انسان کثرت عبادت داشته باشد غفلت، نسیان و خطاها کاهش می‌یابد و دیرتر دچار فراموشی مشود.\nدر این خطبه ملایک به چهار گروه، اما در روایات تقسیم‌بندی دیگری هم هست. \nبا هم منافات ندارد. \nانسان را در تقسیم‌بندی از نظر جنسیت مذکر است یا مؤنث. \nاز نظر سن، کودک است یا جوان، یا میان‌سال\nاز نظر علم می‌شود تقسیم مختلفی کرد عالم است یا جاهل. \nدر روایات هم ملائک از جهات مختلف تقسیم‌بندی شده‌اند.\nمعمولاً خدا به واسطه این ملائکه با پیامبران سخن گفته\nاختلاف در لغت=رفت‌وآمد اوامر و نواهی خدا، قضاوقدر خدا را می‌برند و می‌آورند\nنظر آیت‌الله مکارم: این قضاوقدر منظور وحی خداست. نظر دیگر این قضاوقدر همان اوامر و نواهی، خیر و شر است. اگر کسی به وقتی خدا عملکرد ملائک قضاوقدر خوب می‌آورند وگرنه خدا به آنها می‌فرماید قضاوقدر بد با آنها بفرستید\nنکته مهم: این ملایکه با هم در ارتباط‌اند \nدسته سوم: حفظه لعباده و السدنه لابواب حنانه\nحافظان اعمال ما هستند رقیب عتید دو ملک که هر دو هم کارهای خوب هم کارهای بد را می‌نویسند\nیک نکته لطیف: از رحمت خداست که هر ملک ۱۲ ساعت با ما همراه هستند و هر ملک از پیش ما رفت دیگر نزد ما نمی‌آید؛ لذا تنها در لحظاتی که با ما است شاهد اشتباه ما است و بیشتر در جریان نیست که شاهد بی‌آبرویی اشرف مخلوقات باشد\n حفاظت اینها به دو صورت است: حفظه: ثبت اعمال ما و برخی از ملائکه مسئول حفاظت ما در مقابل گرفتاری‌ها و بلاها هستند (از اعتقادات ما فرزندان ما و…محافظت می‌کنند تا هنگام مرگ) \nالسدنه (دربان) این ملائکه محافظ یک‌سری دربانان درهای بهشت هستند\nنکته: این ملائک با هم در ارتباط هستند آنچه از اعمال ما امروز ثبت می‌شود فردا باعث ورود یا خروج ما از بهشت می‌شود.\n \nدسته چهارم: حاملان عرش الهی: و منهم الثابتهُ فی الارضین السُفلی اقدامُهُم و المارقه من السماءِ العُلیا اعناقهم و الخارجهُ من الاقطارِ ارکانهم \nمارقه (خروج کرده) پاهایشان در پایین‌ترین نقطه زمین و گردنشان از آسمان بالا هم بیرون‌زده بدن آنها آن‌قدر بزرگ است که دست و پاها و…شان از ارز زمین بیرون‌زده\nو المناسبه لقوائم العرش اکتافهم\n مناسبه (تنظیم شده). کتف‌هایشان برای حمل عرش الهی تنظیم شده. \nناکسه دونه أبصارهم متلفّعون تحته باجنحتهم مضروبهٌ بینه\nناکسه (واژگون شده) آنها زیر بار عرش الهی قرار گرفته‌اند وقتی می‌خواهندش را ببینند آن‌قدر عظمت دارد که سرهایشان را پایین می‌اندازند، دور خودشان را با بال‌وپر می‌پیچند از عظمت خدا در نهایت تواضع قرار می‌گیرند\n بین ملائکه حامل عرش خدا و غیر آنها (انس و جن و سایر ملائکه) پرده از عزت و قدرت قرار گرفته\nنکته: هر چه ما از نظر روحی قوی‌تر شویم به ملائکه نزدیک‌تر می‌شویم یکی از راه‌های تقویت روح روز است\nویژگی این ملایکه حاملان عرش: ۱.خدا را با تصویرسازی وهم نمی‌کنند. (در همین خطبه بود که «کمال الاخلاص له نفی الصفات عنه») شکل برای خدا نمی‌سازند. ۲.صفات و ویژگی‌های مخلوقات ها برای خدا حمل نمی‌کنند ۳. خدا را در یک مکان خاص قرار نمی‌دهند ۴. مثل و مانند و شبیه برای خدا قرار نمی‌دهند.\n\nچند نکته در مورد ملائکه: \n۱. ملائکه آیا جسم دارند؟ ۲ پاسخ. پاسخ اول جسم ندارند مجرد محض هستند رکوع و سجود آنها منظور همان خشوع است. پاسخ دوم قول مشهور امامیه است آن‌ها جسم دارند؛ ولی جسم لطیف نورانی نه عنصری. مرحوم مجلسی در بحار جلد ۵۶ صفحه ۲۰۲ به این مطلب اشاره فرموده و در ادامه این را بیان داشته که چون ملائکه جسم لطیف دارند تبدیل به قالب‌های دیگر برایشان امکان دارد\n۲. قرآن و روایات و اصناف مختلف برای ملائکه می‌گویند یکی از این ملائک حاملان عرش خدا هستند ما یک عرش در قرآن داریم یک کرسی. کرسی (در آیه الکرسی به آن اشاره شده) به تخت کوتاه و ارش به تخت بلند پادشاهی گویند خداخدا وقتی می‌خواهد فرمان آن‌چنانی صادر کند از ارش فرمان می‌دهد به طور مثال برای ایجاد کائنات از عرش فرمان می‌دهد عظمت عرش آن‌چنان است حاملان عرش خدا با آن عظمت نمی‌توانند به آن نگاه کنند . \n۳. در روایتی که در منهاج البراعه شرح نهج‌البلاغه اثر میرزا حبیب‌الله خویی آمده که حاملان عرش خدا با ذکر با حول و لا قوه الا بالله العلی العظیم و صل علی‌محمد واله الطیبین عرش خدا را نگه داشته‌اند\n ما هم در گرفتاری‌های دنیا به این ذکر توسل کنیم\n۴. در سوره غافر آیه ۸ آمده «فرشتگانی که عرش (باعظمت الهی) را بر دوش گرفته و آنان که پیرامون عرش‌اند به تسبیح و ستایش حق مشغول‌اند، هم خود به خدا ایمان دارند و هم برای اهل ایمان از خدا آمرزش و مغفرت می‌طلبند…» \n اگر مؤمن باشیم مشمول استغفار حاملان عرش می‌شویم\n۵.آیا می‌توان ملایکه را دید؟ طبق آنچه در قرآن به‌عنوان‌مثال در مورد حضرت ابراهیم آمده و همچنین روایات به‌خصوص روایتی از پیامبر صلی‌الله که به عمران بن حصین در جریانی که به واسطه اخلاصش قادر به دیدن ملائکه شده بود راه دیدن ملائکه بسته نیست اگر خودمان را شبیه ملایکه کنیم قادر به دیدن آنها خواهیم بود","بخش ششم:\nمتن:\nثُمَّ جَمَعَ سُبْحَانَهُ مِنْ حَزْنِ الْأَرْضِ وَ سَهْلِهَا وَ عَذْبِهَا وَ سَبَخِهَا تُرْبَةً سَنَّهَا بِالْمَاءِ حَتَّی خَلَصَتْ وَ لَاطَهَا بِالْبِلَّةِ حَتَّی لَزَبَتْ، فَجَبَلَ مِنْهَا صُورَةً ذَاتَ أَحْنَاءٍ وَ وُصُولٍ وَ أَعْضَاءٍ وَ فُصُولٍ أَجْمَدَهَا حَتَّی اسْتَمْسَکتْ وَ أَصْلَدَهَا حَتَّی صَلْصَلَتْ لِوَقْتٍ مَعْدُودٍ وَ أَمَدٍ [أَجَلٍ] مَعْلُومٍ، ثُمَّ نَفَخَ فِیهَا مِنْ رُوحِهِ [فَتَمَثَّلَتْ] فَمَثُلَتْ إِنْسَاناً ذَا أَذْهَانٍ یجِیلُهَا وَ فِکرٍ یتَصَرَّفُ بِهَا وَ جَوَارِحَ یخْتَدِمُهَا وَ أَدَوَاتٍ یقَلِّبُهَا وَ مَعْرِفَةٍ یفْرُقُ بِهَا بَینَ الْحَقِّ وَ الْبَاطِلِ وَ الْأَذْوَاقِ وَ الْمَشَامِّ وَ الْأَلْوَانِ وَ الْأَجْنَاسِ مَعْجُوناً بِطِینَةِ الْأَلْوَانِ الْمُخْتَلِفَةِ وَ الْأَشْبَاهِ الْمُؤْتَلِفَةِ وَ الْأَضْدَادِ الْمُتَعَادِیةِ وَ الْأَخْلَاطِ الْمُتَبَاینَةِ مِنَ الْحَرِّ وَ الْبَرْدِ وَ الْبَلَّةِ وَ الْجُمُودِ [وَ الْمَسَاءَةِ وَ السُّرُورِ].\nوَ اسْتَأْدَی اللَّهُ سُبْحَانَهُ الْمَلَائِکةَ وَدِیعَتَهُ لَدَیهِمْ وَ عَهْدَ وَصِیتِهِ إِلَیهِمْ فِی الْإِذْعَانِ بِالسُّجُودِ لَهُ وَ الْخُنُوعِ لِتَکرِمَتِهِ، فَقَالَ سُبْحَانَهُ [لَهُمْ] اسْجُدُوا لِآدَمَ فَسَجَدُوا إِلَّا إِبْلِیسَ [وَ قَبِیلَهُ اعْتَرَتْهُمُ] اعْتَرَتْهُ الْحَمِیةُ وَ غَلَبَتْ [عَلَیهِمُ] عَلَیهِ الشِّقْوَةُ وَ [تَعَزَّزُوا] تَعَزَّزَ بِخِلْقَةِ النَّارِ وَ [اسْتَوْهَنُوا] اسْتَوْهَنَ خَلْقَ الصَّلْصَالِ، فَأَعْطَاهُ اللَّهُ النَّظِرَةَ اسْتِحْقَاقاً لِلسُّخْطَةِ وَ اسْتِتْمَاماً لِلْبَلِیةِ وَ إِنْجَازاً لِلْعِدَةِ، فَقَالَ\nفَإِنَّک مِنَ الْمُنْظَرِینَ إِلی یوْمِ الْوَقْتِ الْمَعْلُومِ.\nترجمه:\nو همواره تسبیح می‌گویند و خسته نمی‌شوند.\nهیچ‌گاه خواب چشمان، آنها را فرو نمی‌گیرد و عقلشان گرفتار سهو و خطا نمی‌شود، بدن آنها به سستی نمی‌گراید و غفلت نسیان، بر آنان عارض نمی‌شود.\nگروهی از آنان امنای وحی او و زبان او به‌سوی پیامبران‌اند و پیوسته برای رساندن حکم و فرمانش در رفت و آمدند و جمعی دیگر حافظان بندگان اویند و دربانان بهشتش. بعضی از آنها پاهایشان در طبقات پایین زمین ثابت و گردن‌هایشان از آسمان بالا، گذشته و ارکان وجودشان از اقطار جهان، بیرون رفته و شانه‌های آنها برای حفظ پایه‌های عرش خدا آماده است و در برابر عرش او چشم‌های خود را پایین افکنده، در زیر آن بال‌های خود را به خود پیچیده‌اند. در میان آنها و کسانی که در مراتب پایین‌تر قرار دارند، حجاب‌های عزّت و پرده‌های قدرت فاصله افکنده است. (آنها چنان در معرفت الهی پیش رفته‌اند که) هرگز پروردگار خود را در وهم و ذهن خود تصویر نمی‌کنند و صفات مخلوقان را برای او قائل نمی‌شوند. هرگز او را در مکانی محدود نمی‌سازند و با نظایر و امثال به او اشاره نمی‌کنند.\nسپس خداوند سبحان، مقداری خاک از قسمت‌های سخت و نرم زمین و بخش‌های شیرین و شوره‌زار گرد آورد و آب بر آن افزود و آن را با رطوبت آمیخت تا به‌صورت موجودی چسبناک درآمد و از آن صورتی آفرید که دارای خمیدگی‌ها و پیوندها و اعضا و مفاصل بود. سپس آن را سفت و جامد کرد تا خود را نگه دارد و صاف و محکم و خشک ساخت و این حال تا وقت معین و سرانجام معلومی ادامه یافت.\nسپس از روح خود در او دمید و به‌صورت انسانی درآمد دارای نیروهای عقلانی که او را در جهات مختلف به حرکت وامی‌دارد و فکری که به‌وسیله آن (در موجودات مختلف) تصرّف می‌نماید و اعضایی که آنها را به خدمت می‌گیرد و ابزاری که برای انجام مقاصدش آنها را زیرورو می‌کند و شناختی که به‌وسیله آن حق را از باطل جدا می‌سازد و طعم‌های مختلف و بوهای گوناگون و رنگ‌ها و اجناس مختلف را از یکدیگر باز می‌شناسد، این در حالی است که او را معجونی از رنگ‌های مختلف و ترکیبی از اشیای همسان و نیروهای متضاد و اخلاط مختلف از حرارت و برودت و رطوبت و خشکی قرار داد.\n\nخداوند سبحان از فرشتگان خواست تا ودیعه‌ای را که نزد آنها بود ادا کنند و پیمانی را که با او درباره سجود برای آدم و خضوع برای بزرگداشت او بسته بودند عمل نمایند و فرمود: برای آدم سجده کنید همه سجده کردند جز ابلیس که خشم و غضب و کبر و نخوت او را فراگرفت و شقاوت و بدبختی بر وی غلبه کرد، به آفرینش خود افتخار نمود و خلقت آدم را از گِل خشکیده، سبک شمرد.\nخداوند خواسته او را پذیرفت چرا که مستحقّ غضب الهی بود و می‌خواست امتحان را بر بندگان تمام کند و وعده‌ای را که به او داده بود، تحقّق بخشد. فرمود: تو از مهلت داده شدگانی (نه تا روز قیامت بلکه) تا روز و وقت معینی.\nتفسیر:\nخلقت انسان:\n💠ثُمَّ جَمَعَ سُبْحَانَهُ مِنْ حَزْنِ الْأَرْضِ وَ سَهْلِهَا وَ عَذْبِهَا وَ سَبَخِهَا \nبعد از خلقت آسمان و زمین مدتی که گذشت، خداوند از گوشه‌گوشهٔ زمین خاک نرم و خشن سنگلاخی [حزن] خاک شیرین و شوره‌زار [سبَخ] را جمع کرد.\n💠تُرْبَةً سَنَّهَا بِالْمَاءِ حَتَّی خَلَصَتْ\nبر خاک‌ها آب ریخت تا اینکه خالص شود. \nخاک سفت کلوخ است باید در آب نم بکشد تا خاک مختلف با هم یکی شود و خالص شود.\nنکته: \n «سنها الماء، الف و لام عهد ذکری . \nیعنی همان آبی که ماده اولیه خلقت بود در وجود آدم هم استفاده شد.» \n«ثم جمعَ» جمع چهار خاک مختلف: \nخاک‌های مختلف طبایع و استعداد مختلف دارد. \nانسان منطقه دریایی، با منطقه بیابانی، و کوهستانی، خصوصیت خلقیات، و استعداد متفاوت در وجود خود دارد.\n💠وَ لَاطَهَا بِالْبِلَّةِ حَتَّی لَزَبَتْ\nخدای متعال خاک‌ها را با رطوبت [بلّه] به هم مخلوط کرد. تا اینکه به گل چسبنده تبدیل شد.\n💠فَجَبَلَ مِنْهَا صُورَةً ذَاتَ أَحْنَاءٍ وَ وُصُولٍ وَ أَعْضَاءٍ وَ فُصُولٍ\nاز گل به وجود آمده یک صورتی خلق کرد که اطراف بدن [احناء] هریک باحالت خاص. \nقفسه سینه دارای انحنا \nصورت نیم‌دایره پهن، \nعلاوه بر انحنا بدن وصولی هم بوده، به‌هم‌چسبیده . \nاستخوان‌های ساعد و ران تا زانو بلند و متصل‌به‌هم مفاصلی خلق کرد تا هر استخوانی را به استخوان دیگر وصل کرد.\nاین چهار ویژگی که کارکرد انسان به آن وابسته است. \nاگر مفاصل نبود هیچ‌کدام از کارکرد امروزی بشر نبود. \nهمه اینها در کنار هم انسان را برای زندگی در دنیا شکل می‌دهد و زندگی را فراهم می‌کند.\n\nمرحله بعد از مجسمه انسان: \n💠أَجْمَدَهَا حَتَّی اسْتَمْسَکتْ\nخدا او را جامد کرد. \nدر همان حالت قرار داد تا گل نرم خود را بگیرد و سفت شود.\n💠وَ أَصْلَدَهَا حَتَّی صَلْصَلَتْ لِوَقْتٍ مَعْدُودٍ وَ أَمَدٍ [أَجَلٍ] مَعْلُومٍ\nبه‌صورت صاف او را قرار داد تا اینکه خشک شود [صلصلت] و رطوبت از وجود انسان برود. \nگل را مدتی رها کرد تا وقت و زمان خاصی که موردنظر خدا بود، فرابرسد.\nدر روایات ۴۰ و ۱۲۰ روز آمده آن‌هم روز ماورایی نه روز دنیایی.\nچرا خدا جسم را رها کرد!! \nبا یک اراده خشک می‌کرد، با یک اراده روح دمیده می‌شد. \nولی این کار نکرد تا به فرزندان آدم بیاموزد عجله نکنید، مرحله‌به‌مرحله، با تأنی، هر چیزی به‌وقت خود انجام گیرد، باعجله به مقصود بالا نمی‌رسید.\n💠ثُمَّ نَفَخَ فِیهَا مِنْ رُوحِهِ\nاز روح در او دمید، آب‌وگل مجسمه‌ای با دمیدن روح تبدیل به انسان شد.\n«خلقتُ من روحی حجر - ۲۹» \nاگر ترجمه شود از روح خودم در او دمیدم \nمخالف با توحید است . \nخدا مرکب نیست جزء ندارد. او بسیط است. \n «من روحی» بخش‌پذیر نیست . \nمگر خدا اجزا و قسمت دارد که بخشی از آن را بدمد. \nهرکسی به اجزا نیازمند است مرکب و محتاج است خدا نمی‌تواند باشد.\nروایات: خدا ملکی را خلق کرد آن ملک روح بود می‌دمید. \nقولی: روحی را خلق کرد و در آن دمید و گفت روح من؛ چون می‌خواست آن را گرامی بدارد. مانند: \nشما چیزی و کسی را به خود نسبت می‌دهید که او را ارزشمند کنید می‌گویید دوست و رفیق من!!! \nپس روح انسان روح خدا نیست و هیچ تناسبی بین این دو وجود ندارد، خدا روح و جسم ندارد ذات است، مرکب نیست بسیط است.\nاین انسان چه ویژگی دارد!\n💠[فَتَمَثَّلَتْ] فَمَثُلَتْ إِنْسَاناً ذَا أَذْهَانٍ یُجِیلُهَا\nآب‌وگل و مجسمه انسانی که در او روح دمیده شد. نه‌تنها ذهن داد؛ بلکه صاحب ذهن‌های متفاوتی که به حرکت و جولان در می‌آورد و مشکلات و سؤال‌ها را حل می‌کند.\nهر انسانی صاحب اذهان، ادراکات مختلف، قوهٖٔ تخیل، قوهٔ حفظ در وجود دارد. \nاما موضوع مهم زمانی انسان شد که در او روح دمیده شد. \nآنچه که باعث فکر و اندیشه انسان است مغز سر نیست. به سبب روح بوده که متفکر شده، از مغز کاری بر نمی‌آید.\nفرق ذهن و فکر: \nذهن در مرتبه اول است با خود بیندیشد، برنامه‌ریزی کندکار ذهن است، داخل است، \nوقتی در بیرون خواست عملیاتی کند، فکر تخیلی نیست، باید با واقعیت‌ها مطابقت و برنامه انجام دهد که کار فکر است. \nذهن در وهله اول، فکر در مرحله دوم.\nفکر و عقل در جسم نیست در روح است. \nبه‌محض مرگ ذهن همان است؛ اما ساده‌ترین مسئله را نمی‌داند. \nمغز انسان شیء ای است که از روح دستور می‌گیرد. ولی بتن‌هایی قادر بکاری نیست.\n💠وَ فِکرٍ یتَصَرَّفُ بِهَا وَ جَوَارِحَ یخْتَدِمُهَا\nخداوند دمید. اذهان و افکار داد، جوارحی داد که به خدمت بگیرد. \nدست، گوش، چشم در خدمت انسانیت باشد.\n💠وَ أَدَوَاتٍ یقَلِّبُهَا\nبه انسان ابزار و آلات داد تا به مقاصد خود برسد. \nبرای رسیدن به مقصد این چهار مرحله را عطا کرد. \n۱- طرح ذهنی \n۲- عملیاتی‌کردن این طرح مطابق با واقعیت \n۳- استفاده از جوارح \n۴- استفاده از ابزار و آلات. \nدر مسیر رسیدن به اهداف این چهار مرحله را بکار گیرد نه اینکه مشغول به پرورش جسم باشد.\n💠وَ مَعْرِفَةٍ یفْرُقُ بِهَا بَینَ الْحَقِّ وَ الْبَاطِلِ\nخداوند شناخت داد به انسان، تا بین حق و باطل فرق بگذارد. \nامر معنوی، قدرتی در روح قرار داد که حق و باطل را تمیز بدهد.\n💠وَ الْأَذْوَاقِ وَ الْمَشَامِّ وَ الْأَلْوَانِ وَ الْأَجْنَاسِ\n۱ - از این معرفت برای شناخت ذائقه‌های مختلف. \n۲- بوهای مختلف را تشخیص دهد. \n۳ - از این معرفت، شناخت رنگ‌ها و اجناس داد.\nاجناس چیست!! \n۱ - شناخت جنس زمخت و نرم، سنگ نرم و خشن، حس لامسه. \n۲- قولی: اجناس یعنی گروه، جنس انسان، جنس حیوان، جنس درخت. \n💠مَعْجُوناً بِطِینَةِ الْأَلْوَانِ الْمُخْتَلِفَةِ\nانسان را طوری خلق کرد که دارای الوان مختلف، همه انسان‌ها با طینت و رنگ مختلف آفریده شدند. به دو دلیل: \n۱. خاک انسان را از جاهای مختلف جمع کرد رنگ‌ها متفاوت است. \n۲. همین جسم است متشکل از رنگ‌های مختلف، مو سیاه، دندان سفید، خون قرمز، صورت و لب هرکدام رنگی، \nهمه یکدست سفید می‌بود مشمئزکننده، و ترکیب رنگ‌ها انسان را دلپذیر کرده است.\n💠وَ الْأَشْبَاهِ الْمُؤْتَلِفَةِ وَ الْأَضْدَادِ الْمُتَعَادِیةِ\nاشیا شبیه هم مانند رگه‌های به هم شبیه ولی وظیفه هر کدام مختلف. \nچیزهای ضد را در کنار هم الفت بینشان قرار دارد، گوشت نرم بااستخوان محکم و سفت . \nشیر سفید و شیرین مادر از میان خون قرمز بدطعم.\n💠وَ الْأَخْلَاطِ الْمُتَبَاینَةِ مِنَ الْحَرِّ وَ الْبَرْدِ وَ الْبَلَّةِ وَ الْجُمُودِ\nعلاوه بر ظواهر شبیه و متضاد مزاج‌های چهارگانه قرار داد که این مزاج‌ها پایه طب سنتی است. \nگرما - صفرا \nسرما - بلغم \nرطوبت - دموی \nخشک - سودا \nاین مزاج‌ها باید در حالت متعادل باشد. گاهی در شرایطی یکی از آنها غالب است. \nدر تابستان که هوا گرم، رطوبت هوا و بدن کم است شب‌ها کوتاه‌اند چون نیاز خواب همان‌قدر است. \nاما در زمستان سرد، رطوبت هوا و بدن زیاد، و سبب سنگینی انسان و نیاز خواب بیشتر، لذا شب‌ها بلند است. \nخداوند در عالم و انسان مزاج‌های مختلف را رعایت کرده است.\n💠والساءَ السُّرُورِ\nشادی و غم را در کنار هم برای انسان قرار داد\n\nویژگی بعد از دمیدن روح انسان:\n💠وَ اسْتَأْدَی اللَّهُ سُبْحَانَهُ الْمَلَائِکةَ وَدِیعَتَهُ لَدَیهِمْ\nبه ملائک فرمود: \nحق ودیعه و پیمانی که بستیم را رعایت کنید. \n «اِنی خالقٌ بشرٌ من صلصال من حمإ مَسنون،،،،فَعقَو له ساجدین حجر - ۲۹» \nخلق انسان تمام شد بر او سجده کنید، عهدی که از قبل بستیم وقت آن رسیده در مقابل آدم سجده کنید.\nنکته: \nخدا از قبل هم می‌توانست به ملائک چیزی نگوید. بل از خلق با این ویژگی‌ها و سفارش مقدمه‌چینی کرد برای امر مهم و شرایط را فراهم کرد. \nو ملائک هم جز بر خدا سجده نداشتند پس باید به این معرفت برسند که سجده بر آدم کنند. \nچنین مواردی در امور اجتماعی و زندگی فردی برای مردم رعایت شود. باید اغنای عمومی باشد، از قبل شرایط را فراهم و عموم را توجیه کرد. \nاین رفتار به آرامش پس از اقدام کمک می‌کند.\n💠وَ عَهْدَ وَصِیتِهِ إِلَیهِمْ فِی الْإِذْعَانِ بِالسُّجُودِ لَهُ وَ الْخُنُوعِ لِتَکرِمَتِهِ\nخضوع کنید برای اینکه انسان را گرامی بدارید. \nما انسان را گرامی داشتیم شما هم گرامی بدارید.\n💠فَقَالَ سُبْحَانَهُ [لَهُمْ] اسْجُدُوا لِآدَمَ فَسَجَدُوا إِلَّا إِبْلِیسَ\nاعتَرتَهُا الحمیَّه و غلبَت علیهِ الشِقوه \nدو چیز مانع ابلیس از سجده شد. \nفراگرفت [اعترت] ابلیس را خشم و غصب. [حمیه] ابلیس این صحنه را که دید با عبادت و ویژگی خود مقایسه کرد و غرور و کبر بر او عارض شد و شقاوت بر او غلبه کرد.\nعامل اصلی انحرافات درون انسان است. \nشقاوت یک عنصر درونی که این عنصر به کبر و آفات تبدیل می‌کند؛ لذا مشکل از درون خود انسان عامل می‌شود.\nنکته: \nاین سجده چه نوع سجده‌ای بود!! \nالف) سجده پرستش بود \nب) پرستش نبود. \nج) تکریم بود. \nمانند خم‌شدن در برابر عالم بزرگی. \nاین خم‌شدن نیت رکوع نیست احترام و تکریم است.\nبه سجده افتادن، آنچه که صحیح است از امام رضا ع نقل شده: \nملائک وقتی به سجده افتادند برای عبودیت و لله بود. ازیک‌طرف سجده کردند برای خدا و احترام کردند برای آدم . \nاز اینکه آدم محترم شده و ارزش پیدا کرده بود، چون ما اهل‌بیت در صلب او بودیم این سجده به احترام ما بود.\n💠وَ [اسْتَوْهَنُوا] اسْتَوْهَنَ خَلْقَ الصَّلْصَالِ\nادعایی که باعث شد ابلیس سجده نکرد. ماده اولیه خود را نار و بر آن افتخار کرد و آدم را خاک و کوچک و حقیر شمرد.\nنکته: \nقضاوت‌های باطل در جامعه که دچار معادلات غلط می‌شوند. \nاز کجا معلوم نار بهتر از خاک باشد. \nمگر آدم به جسم است که مقایسه ناری و خاکی بشود. حقیقت آدم و روح اوست. این امر قیاس سبب دورشدن ابلیس شد.\n💠فَأَعْطَاهُ اللَّهُ النَّظِرَةَ اسْتِحْقَاقاً لِلسُّخْطَةِ \nخدا یک مهلتی به او داد. تا بیش‌ازپیش غرق در انحراف بشود تا او را مجازات کند. \n «همان عذاب استدراج»\n💠وَ اسْتِتْمَاماً لِلْبَلِیةِ\nخدا با مهلت‌دادن امتحان بندگان را کامل کرد. \nزندگی در دنیا بدون دشمن و جهاد معنا نداشت. \nظهور و بروز استعداد درونی به این مجاهدت‌ها و ایستادن در برابر شیطنت‌ها شکوفا می‌شود.\n💠وَ اسْتِتْمَاماً لِلْبَلِیةِ وَ إِنْجَازاً لِلْعِدَةِ، فَقَالَ: فَإِنَّک مِنَ الْمُنْظَرِینَ إِلی یوْمِ الْوَقْتِ الْمَعْلُومِ\nخداوند او را مهلت داد تا وقت معینی تا وعدهٔ حتمی که عذاب است را محقق کند.\nاین وقت تا چه زمانی هست اقوال مختلف است!! \nقولی: او تا قیامت وقت خواست، فرمود تا زمان معلوم، منظور پایان دنیا. \nقولی: منظور از وقت معلوم زمان مرگ شیطان، ولی مرگ او معلوم نیست. \nقول معروف‌تر: وقت معلوم، زمان ظهور است که بساط شیطان جمع می‌شود.\nآیا با رفتن شیطان بساط گناه جمع می‌شود؟!! \nخیر \nشیطان یکی از عوامل است، عامل هم‌طراز با شیطان «نفس» است. \nدر عصر ظهور گناه از بین نمی‌رود، اختیارات گرفته نمی‌شود. \nمانند ماه مبارک که شیطان در غل‌وزنجیر است؛ اما باز گناه صورت می‌گیرد. \nچون نفس، تخیل، وهم در غل‌وزنجیر و دست‌وپابسته نیست. \nشیطان هم از بین برود استعداد گناه در وجود انسان هست.","بخش هفتم:\nمتن:\nثُمَّ أَسْکنَ سُبْحَانَهُ آدَمَ دَاراً أَرْغَدَ فِیهَا [عِیشَتَهُ] عَیشَهُ وَ آمَنَ فِیهَا مَحَلَّتَهُ وَ حَذَّرَهُ إِبْلِیسَ وَ عَدَاوَتَهُ، فَاغْتَرَّهُ عَدُوُّهُ نَفَاسَةً عَلَیهِ بِدَارِ الْمُقَامِ وَ مُرَافَقَةِ الْأَبْرَارِ، فَبَاعَ الْیقِینَ بِشَکهِ وَ الْعَزِیمَةَ بِوَهْنِهِ وَ اسْتَبْدَلَ بِالْجَذَلِ وَجَلًا وَ [بِالاعْتِزَازِ] بِالاغْتِرَارِ نَدَماً، ثُمَّ بَسَطَ اللَّهُ سُبْحَانَهُ لَهُ فِی تَوْبَتِهِ وَ لَقَّاهُ کلِمَةَ رَحْمَتِهِ وَ وَعَدَهُ الْمَرَدَّ إِلَی جَنَّتِهِ وَ أَهْبَطَهُ إِلَی دَارِ الْبَلِیةِ وَ تَنَاسُلِ الذُّرِّیةِ.\nوَ اصْطَفَی سُبْحَانَهُ مِنْ وَلَدِهِ أَنْبِیاءَ، أَخَذَ عَلَی الْوَحْی مِیثَاقَهُمْ وَ عَلَی تَبْلِیغِ الرِّسَالَةِ أَمَانَتَهُمْ لَمَّا بَدَّلَ أَکثَرُ خَلْقِهِ عَهْدَ اللَّهِ إِلَیهِمْ فَجَهِلُوا حَقَّهُ وَ اتَّخَذُوا الْأَنْدَادَ مَعَهُ وَ اجْتَالَتْهُمُ الشَّیاطِینُ عَنْ مَعْرِفَتِهِ وَ اقْتَطَعَتْهُمْ عَنْ عِبَادَتِهِ؛ فَبَعَثَ فِیهِمْ رُسُلَهُ وَ وَاتَرَ إِلَیهِمْ أَنْبِیاءَهُ لِیسْتَأْدُوهُمْ مِیثَاقَ فِطْرَتِهِ وَ یذَکرُوهُمْ مَنْسِی نِعْمَتِهِ وَ یحْتَجُّوا عَلَیهِمْ بِالتَّبْلِیغِ وَ یثِیرُوا لَهُمْ دَفَائِنَ الْعُقُولِ وَ یرُوهُمْ آیاتِ الْمَقْدِرَةِ مِنْ سَقْفٍ فَوْقَهُمْ مَرْفُوعٍ وَ مِهَادٍ تَحْتَهُمْ مَوْضُوعٍ وَ مَعَایشَ تُحْییهِمْ وَ آجَالٍ تُفْنِیهِمْ وَ أَوْصَابٍ تُهْرِمُهُمْ وَ أَحْدَاثٍ [تَتَتَابَعُ] تَتَابَعُ عَلَیهِمْ \n\nترجمه:\nسپس خداوند سبحان، آدم را در خانه‌ای سکنی بخشید که زندگی‌اش را در آن پر نعمت و گوارا کرده بود و جایگاه او را امن‌وامان ساخته بود و او را از ابلیس و عداوت و دشمنی‌اش بر حذر داشت، ولی (سرانجام) دشمنش او را فریب داد، چرا که بر او حسادت می‌ورزید و از این که او در سرای پایدار و همنشین با نیکان است سخت ناراحت بود.\nآدم یقین خود را به شک‌وتردید او فروخت و تصمیم راسخ را با گفته سُست او مبادله کرد، و به‌خاطر همین موضوع، شادی خود را به ترس و وحشت مبدّل ساخت و فریب شیطانی برای او پشیمانی به بار آورد، سپس خداوند سبحان دامن توبه را برای او گسترد و کلمات رحمتش را به او القا نمود و وعده بازگشت به بهشتش را به او داد و او را به سرای آزمایش (دنیا) و جایگاه توالد و تناسل فرو فرستاد.\n\nخداوند سبحان، از فرزندان آدم پیامبرانی برگزید و از آنها پیمان گرفت که وحی الهی را به‌خوبی حفظ کنند و امانت رسالت را به مردم ابلاغ نمایند، این در زمانی بود که اکثر مردم پیمانی را که خداوند از آنها گرفته بود دگرگون ساختند و همتا و شریکان، برای او قرار دادند و شیاطین، آنها را از معرفت خداوند بازداشتند و از عبادت او جدا کردند، به این دلیل خداوند، پیامبرانش را در میان آنها مبعوث کرد و رسولان خود را پی‌درپی به‌سوی آنان فرستاد تا پیمان فطرت را از آنها مطالبه کنند و نعمت‌های فراموش شده الهی را به آنان یادآوری نمایند و با ابلاغ دستورات او حجّت را بر آنها تمام کنند و گنج‌های پنهانی عقل‌ها را برای آنها آشکار سازند و قدرت خدا را به آنها نشان دهند، از جمله: سقف برافراشته آسمان که بر فراز آنهاست و گاهواره زمین که در زیر پای آنها نهاده شده و وسایل زندگی که حیات به آنها می‌بخشد و سرآمدهای عمر که آنان را فانی می‌سازد و مشکلات و رنج‌هایی که آنان را پیر می‌کند و حوادثی که پی‌درپی بر آنان وارد می‌شود.\n\nتفسیر:\n اسکان آدم: \n💠 ثُمَّ أَسْکنَ سُبْحَانَهُ آدَمَ دَاراً أَرْغَدَ فِیهَا [عِیشَتَهُ] عَیشَهُ\nوقتی آدم خلق شد او را در مکانی مأوی داد. \nآن بهشت نیست نفرمود جنت، صحبت از دار است و به بهشت دار نمی‌گویند.\nدر بین اهل علم آنچه مسلم است آن بهشت موعود نبوده. \nیکی از دلایل: \nالف) رفتن به بهشت عمل به تکلیف می‌خواهد درحالی‌که آدم عملی نداشت بهشت برود. \nب) بهشت جایی است که خروج از آن ممکن نیست. در آن خلود است. \nج) بهشت جایگاه پاکان است، شیطان منفور چگونه بتواند به آنجا راه پیدا کند. \nاگر هم گاهی گفته می‌شود بهشت، جای دنیایی بوده، جای سرسبز، پر از نعمت، تعابیر و تمثیل از بهشت است. \nعیش و مسائل زندگی [ارغد] گسترده بود.\n\n💠 وَ آمَنَ فِیهَا مَحَلَّتَهُ\nجایگاه او را امن قرار داده خطر و دلهره وجود نداشت. \n دو ویژگی نعمت دنیایی: \n۱- نعمت فراوان \n۲- کم‌بودن خطر و ناامنی \nامنیت و نعمت دو رکن زندگی بهشتی است.\n💠 وَ حَذَّرَهُ إِبْلِیسَ وَ عَدَاوَتَهُ\nخدا آدم را از ابلیس بر حذر داشت . \nمراقب شیطان و دشمنی او باش از مقام خود خلع شده حسادت دارد.\n💠 فَاغْتَرَّهُ عَدُوُّهُ نَفَاسَةً عَلَیهِ بِدَارِ الْمُقَامِ وَ مُرَافَقَةِ الْأَبْرَارِ \nشیطان به سبب حسادت [نفاسه] آدم را فریب داد. \nاتفاقی که نباید می‌افتاد، افتاد. \n انسان را گول زد، چرا که آدم در جایگاه پایدار بود. \nآن دار جایگاهی بود که خدا او را در آنجا قرارداد. \nشیطان به مسجود بودن او حسد کرد و در صدد انتقام برآمد\nو آدم نه‌تنها در جایگاه همیشگی بود؛ بلکه رفیق خوبان عالم بود. [مرافقه الابرار] \nآدم اولین مخلوق از جنس انسان کاملاً مثبت، فکر نمی‌کرد کسی دشمنی، دروغگویی، خیانت، دورویی داشته باشد فکر می‌کرد همه ملک گونه‌اند و اهل طاعت و عبادت ولی شیطان آمد و آن جملات را گفت.\n💠 فَبَاعَ الْیقِینَ بِشَکهِ\nآدم یقین خود را به شک فروخت. \nیقین یعنی همان حرف خدا بود که مراقب ابلیس باش و دوری کن [حذره]\nشک یعنی، همان جملات شیطان که قسم خورد. \n «و قاسَمَهما آنی لمنَ الناصحین اعراف - ۲۱» \nبه خدا قسم خیرخواه شما هستم. \nاولین قسم دروغ خورده شد و آدم نمی‌دانست؛ چون با دورویی روبرو نشده بود.\n💠 وَ الْعَزِیمَةَ بِوَهْنِهِ وَ اسْتَبْدَلَ بِالْجَذَلِ وَجَلًا\nتصمیم و عزم محکم خود را فروخت و به یک تصمیم سست شیطان مبدل کرد. \nدر یک فضای پر نعمت زندگی و خوشحالی [جذَل] مقامات را تبدیل کرد، دچار ترس شد. ترس دوری از خدا، ترس خشم خدا. \nامرونهی به آدم امرونهی ارشادی بوده یا ترک اولیٰ ولی مرتکب گناه نشده. \nاز مسلّمات شیعه است که پیامبر معصوم است از هر خطا، سهو، نسیان، گناه به‌دور است و همان مقدار ترک اولیٰ سبب ترس او شد.\n\n\n\n💠 بِالاغْتِرَارِ نَدَماً\nآدم پس از فریب دچار پشیمانی شد. \nشیطان وقتی اشتباه کرد سر لجاجت افتاد، کمر همت بست به دشمنی با انسان. در واقع شیطانی برخورد کرد. در ادامه سرازیری اصرار بر خطا کرد. \nاما آدم وقتی اشتباه کرد پشیمان و ناراحت شد. دنبال راه چاره و جبران گشت.\n💠 ثُمَّ بَسَطَ اللَّهُ سُبْحَانَهُ لَهُ فِی تَوْبَتِهِ\nخدای متعال بساط توبه آدم را فراهم کرد. \nدر عالم خطا و اشتباه هست؛ اما در توبه هم باز است.\n💠 وَ لَقَّاهُ کلِمَةَ رَحْمَتِهِ\nالقا کرد، به او فهماند کلمات رحمت را. تا توبه تو پذیرفته شود. \nکلمه رحمت چیست!!! \nالف) همین که معترف به‌اشتباه شد. \n «ربنا ظلمنا انفسَنا و اِن لم تغفر لناو ترحَمنا لنکونن من القوم الظالمین اعراف - ۲۳» \nاعتراف بخطا القا رحمت بود.\nب) توبه‌کردن «فاغفر لی اِنک من الغافرین»  \nج) تأیید بر روایات: راهی نیست جز توسل به خمسه طیبه، کمک‌گرفتن از این خاندان تا مورد بخشش خدا قرار بگیرد.\n💠 وَ وَعَدَهُ الْمَرَدَّ إِلَی جَنَّتِهِ\nبه آدم وعده داد بازگشت [مرّد] به جنت موعود را.\n توبه پذیرفته شده، و وعده بر بهشت حقیقی قیامت باشد.\n💠 وَ أَهْبَطَهُ إِلَی دَارِ الْبَلِیةِ وَ تَنَاسُلِ الذُّرِّیةِ\nخدا او را فرو فرستاد در یک سرزمین امتحان [بلیّه].\nاز زمین امنیت به زمین امتحان، تکاثر تناسل نزول کرد.\n- آدم توبه کرد پذیرفته شد؛ ولی باید هبوط کند. بنا نیست اثر خطا هم بخشیده شود. \nاصل خطابخشش شد؛ اما آثار آن چه می‌شود!!! \nاثر اعمال خیر و شر مهم است. \nاثر وضعی گناه می‌ماند.\n- دنیادار امتحان است، و بنا نیست راحتی باشد و بدون مشکلات. دار سختی است خود را آماده کنید. \nاگر انتظار سختی نداشته باشید به‌محض ورود به مشکل زبان به کفر باز می‌شود.\n- تناسل ذریه، برای تولد و تکثیر نسل است. \nهدف آمدن آدم را به عالم ازدیاد نسل می‌داند. \nقبل از اینکه صحبت از تقوا و عبادت باشد فکر ازدیاد نسل باشید. \nوظیفهٔ تو و فرزندان تو، در ابتدا این است، تکثیر نسل. \n «به آرمان انبیا خیانت نکنید» \n \nنبوت انبیا: \nنبوت عامه: \nدر همه انبیا مشترک است \nانبیا با وحی در ارتباط بوده و رسالت را تبلیغ کنند. \nعلم داشته باشند که جزو وظایف آنهاست.\nنبوت خاصه: \nدر مورد تک‌به‌تک انبیا حرف دارد. \nبعثت موسی، معجزات، حاکم هم‌دورهٔ او، در خصوصیات کلی سخن می‌گوید.\n💠 وَ اصْطَفَی سُبْحَانَهُ مِنْ وَلَدِهِ أَنْبِیاءَ، أَخَذَ عَلَی الْوَحْی مِیثَاقَهُمْ\nخدا از فرزندان آدم، انبیایی برگزید که می‌بایست میثاق می‌بستند که وحی را بتمامه اخذ کنند.\n– عصمت مراتب مختلفی دارد: \n یک بخش عصمت نبی، عدم گناه است. \nبخشی از عصمت نبی، اخبار وحی را به‌درستی بگیرد، به‌درستی حفظ کند، به‌درستی انتقال دهد. \nاگر دچار سهو شود، یا کلمات را خوب نفهمد، از یاد برود، یا در ادا اشتباه بیان کند که دیگر معصوم نیست. \n💠 وَ عَلَی تَبْلِیغِ الرِّسَالَةِ أَمَانَتَهُمْ\nپیمان گرفت که امانت رسالت را به‌درستی تبلیغ و به مردم برسانند.\n💠 لَمَّا بَدَّلَ أَکثَرُ خَلْقِهِ عَهْدَ اللَّهِ إِلَیهِمْ\nاین اتفاق «عهد با انبیا» در موقعیت و زمانی بود که: \n اکثر افراد بشریت عهد الهی را «آلم اعهد الیکم یا بنی آدم آن لا تعبدوا یس. - ۲۰» عهد را تبدیل کردند.\n– یک عهد با انبیا دارد که واسط بین خدا و مردم باشند. \nیک عهد هم با مردم بست و آن را فراموش کردند. انبیا آمدند که عهد فراموش شده را یادآور شوند. \nهمان لحظه‌ای که مردم عهد الهی را با خود، فراموش کردند. \nمنظور عالم ذر است. \nیا همان فطرت است که در وجود تک‌تک انسان قرار داد.\n💠 فَجَهِلُوا حَقَّهُ\nانسان حق پیمان را انجام نداده و نسبت به خدا جهل پیدا کرد. \n💠 وَ اتَّخَذُوا الْأَنْدَادَ مَعَهُ\nمردم برای خدا مثل و شبیه [ند] قرار داده بت‌پرستی کردند. \nاگر اولین علم، علم توحید و خداشناسی معرفی شده، چون سر از جهل و بت‌پرستی در نیاورد. \nبه خدا جهل پیدا شود مشکل بت‌پرستی هم مازاد می‌شود\n💠 وَ اجْتَالَتْهُمُ الشَّیاطِینُ عَنْ مَعْرِفَتِهِ\nشیاطین انسان را منصرف‌کردن [اجتالت] از اینکه به خدا معرفت پیدا کنند.\nابتدا جهل، بعد شرک، مرحله سوم انصراف از معرفت خدا. \nدر مرحله دوم هم خدا دیده می‌شود و هم بت. \nاما در وهله سوم معرفت خدا از دست می‌رود.\n💠 وَ اقْتَطَعَتْهُمْ عَنْ عِبَادَتِهِ\nشیطان انسان را از عبادت و ارتباط باخدا قطع کرد.\n\nفلسفه ارسال رسل: \n💠 فَبَعَثَ فِیهِمْ رُسُلَهُ وَ وَاتَرَ إِلَیهِمْ أَنْبِیاءَهُ\nخدا رسولان را به سمت مردم فرستاد . \nتک‌به‌تک [واتر] انبیا را فرستاد. برای پنج هدف کلی.\n💠 لِیسْتَأْدُوهُمْ مِیثَاقَ فِطْرَتِهِ\n۱- تا اینکه از مردم مطالبه کنند. خدا میثاقی را که با فطرت انسان بسته یادآوری کنند. قول و قرار خدا را عملیاتی و اجرا کنند.\nدر ابتدا چند خط قبل فرمود با مردم عهد بستیم. در این بخش هم «لیستادوا» را فرمود. \nمعلوم است آن عهد با این میثاق فطری یکی هست.\n💠 وَ یذَکرُوهُمْ مَنْسِی نِعْمَتِهِ\n۲- انبیا آمدند نعمت‌های فراموش شده را یادآوری کنند. \nحیات، عقل، فطرت، عمر، محبت علی، بزرگ‌ترین نعمت‌هایی که نسبت به آنها کور نباشید. \nنعمت‌های ظاهری و باطنی فراموش شده، و در مقابل هر نعمت مطالبه‌ای دارد که وظیفه نسبت به آن انجام شود.\n💠 وَ یحْتَجُّوا عَلَیهِمْ بِالتَّبْلِیغِ\n۳- انبیا آمدند با تبلیغی که دارند بر انسان احتجاج کنند. استدلال عقلی آورده حجت را تمام کنند.\n💠 وَ یثِیرُوا لَهُمْ دَفَائِنَ الْعُقُولِ\n۴- انبیا آمدند تا دفینه و قبرستان عقل انسان‌ها را شخم بزنند. \nعقل و فطرت زیر خروارها خاک پنهان شده. \nبا هر گناه صدای فطرت کم می‌شود. ناگه دفن می‌شود و هیچ آلارمی بیرون نمی‌دهد. \nانبیا این دفن شده را بیرون می‌کشند. \n💠 وَ یرُوهُمْ آیاتِ الْمَقْدِرَةِ\n۵- آمدند نشانه‌های قدرت خدا که عالم را فراگرفته نشان بدهند.\nنمونه‌های از قدرت خدا: \n💠 مِنْ سَقْفٍ فَوْقَهُمْ مَرْفُوعٍ\nالف) اولین قدرت خدا آسمان مرفوعی که بالای سر شماست.\n💠 وَ مِهَادٍ تَحْتَهُمْ مَوْضُوعٍ\nب) قدرت بر مهد و گهواره زمین که زیر پای انسان گسترد.\n💠 وَ مَعَایشَ تُحْییهِمْ وَ آجَالٍ تُفْنِیهِمْ\nج) اسباب زندگی و معاش، ابزار و آلات صنعت و غیرصنعتی برای انسان فراهم کرد. \nو بخشی از قدرت خدا برای عمر شما وقت معینی [آجال] قرار داد.\n💠 وَ أَوْصَابٍ تُهْرِمُهُمْ\nد) از قدرت خداست که زندگی شما را سراسر با پیچیدگی [اوصاب] و مشکلات کرد. \nقدرت دارد که یک مشکل بتواند انسان را به اوج پیری و فرتوتی [تهرِم] برساند. \nچه کسی می‌توان مقابل این قدرت بایستد. \nپیری را پس برند.\nو مشکل را نپذیرد.\n💠 وَ أَحْدَاثٍ تَتَابَعُ عَلَیهِمْ\nه) از قدرت خداست که حوادث را پی‌درپی [تتابع] بر انسان وارد کند\nمرگ، معاش، حوادث، زمین، آرامش، اسمان، قدرت‌های خدا عواملی هستند که انبیا آمدند که بگویند قدرت خدا ما فوق قدرت‌هاست، از قدرت‌های پوشالی نهراسید.","بخش هشتم:\nمتن:\nوَ لَمْ یخْلِ اللَّهُ سُبْحَانَهُ خَلْقَهُ مِنْ نَبِی مُرْسَلٍ أَوْ کتَابٍ مُنْزَلٍ أَوْ حُجَّةٍ لَازِمَةٍ أَوْ مَحَجَّةٍ قَائِمَةٍ، رُسُلٌ لَا تُقَصِّرُ بِهِمْ قِلَّةُ عَدَدِهِمْ وَ لَا کثْرَةُ الْمُکذِّبِینَ لَهُمْ مِنْ سَابِقٍ سُمِّی لَهُ مَنْ بَعْدَهُ أَوْ غَابِرٍ عَرَّفَهُ مَنْ قَبْلَهُ. عَلَی ذَلِک نَسَلَتِ الْقُرُونُ و مَضَتِ الدُّهُورُ وَ سَلَفَتِ الْآبَاءُ وَ خَلَفَتِ الْأَبْنَاءُ.\nإِلَی أَنْ بَعَثَ اللَّهُ سُبْحَانَهُ مُحَمَّداً [صلی‌الله علیه و آله] رَسُولَ اللَّهِ لِإِنْجَازِ عِدَتِهِ وَ إِتْمَامِ نُبُوَّتِهِ مَأْخُوذاً عَلَی النَّبِیینَ مِیثَاقُهُ، مَشْهُورَةً سِمَاتُهُ کرِیماً مِیلَادُهُ، وَ أَهْلُ الْأَرْضِ یوْمَئِذٍ مِلَلٌ مُتَفَرِّقَةٌ وَ أَهْوَاءٌ مُنْتَشِرَةٌ وَ طَرَائِقُ مُتَشَتِّتَةٌ، بَینَ مُشَبِّهٍ لِلَّهِ بِخَلْقِهِ أَوْ مُلْحِدٍ فِی اسْمِهِ أَوْ مُشِیرٍ إِلَی غَیرِهِ، فَهَدَاهُمْ بِهِ مِنَ الضَّلَالَةِ وَ أَنْقَذَهُمْ بِمَکانِهِ مِنَ الْجَهَالَةِ، ثُمَّ اخْتَارَ سُبْحَانَهُ لِمُحَمَّدٍ صلی‌الله علیه و آله لِقَاءَهُ وَ رَضِی لَهُ مَا عِنْدَهُ وَ أَکرَمَهُ عَنْ دَارِ الدُّنْیا وَ رَغِبَ بِهِ عَنْ مَقَامِ الْبَلْوَی فَقَبَضَهُ إِلَیهِ کرِیماً، وَ خَلَّفَ فِیکمْ مَا خَلَّفَتِ الْأَنْبِیاءُ فِی أُمَمِهَا إذْ لَمْ یتْرُکوهُمْ هَمَلًا بِغَیرِ طَرِیقٍ وَاضِحٍ وَ لَا عَلَمٍ قَائِمٍ.\n\nترجمه:\nو خداوند سبحان هیچ‌گاه جامعه بشری را از پیمان مرسل، یا کتاب آسمانی، یا دلیلی قاطع، یا راهی روشن خالی نگذارده است، پیامبرانی که کمی نفراتشان و فزونی دشمنان و تکذیب‌کنندگانشان، آنها را از انجام وظایف، باز نمی‌داشت، پیامبرانی که بعضی به ظهور پیامبری آینده بشارت می‌دادند و بعضی از طریق پیامبر پیشین شناخته شده بودند و به‌این‌ترتیب قرن‌ها گذشت و روزگاران، سپری شد، پدران رفتند و فرزندان، جانشین آنان شدند.\n\n(این وضع همچنان ادامه داشت) تا این که خداوند سبحان محمّد رسول‌الله (صلی‌الله علیه و آله) را برای وفای به عهد خویش و کامل‌کردن نبوّتش مبعوث کرد. این در حالی بود که از همه پیامبران، پیمان درباره او گرفته شده بود (که به او ایمان بیاورند و بشارت ظهورش را به پیروان خویش بدهند) و درحالی‌که نشانه‌هایش مشهود و میلادش ارزنده بود و در آن روز مردم زمین، دارای مذاهب پراکنده و افکار ضدونقیض و راه‌ها و عقاید پراکنده بودند: گروهی خدا را به مخلوقاتش تشبیه می‌کردند و گروهی نام او را بر بت‌ها می‌نهادند و بعضی به غیر او اشاره و دعوت می‌نمودند، امّا خداوند آنها را به‌وسیله آن حضرت از گمراهی رهایی بخشید و باوجود پربرکتش، آنان را از جهالت نجات داد.\nسپس خداوند سبحان، لقای خویش را برای محمّد صلی‌الله علیه و آله انتخاب کرد و آنچه را نزد خود داشت برای او پسندید و او را با رحلت و انتقال از دار دنیا به سرای آخرت گرامی داشت و از گرفتاری در چنگال مشکلات نجات بخشید.\nآری در نهایت احترام او را قبض روح کرد، درود خدا بر او و آلش باد! او هم آنچه را انبیای پیشین برای امّت خود به یادگار گذارده بودند، در میان شما به‌جای نهاد چرا که آنها هرگز امّت خود را بی‌سرپرست و بی آن که راهی روشن در پیش پایشان بنهند و پرچمی برافراشته نزد آنان بگذارند، رها نمی‌کردند.\nتفسیر:\nبعثت خاصه انبیاء: \n💠 وَ لَمْ یخْلِ اللَّهُ سُبْحَانَهُ خَلْقَهُ\nخدای متعال هیچگاه زمین را از وجود حجت خدا خالی نگذاشت. \nبندگان خود را بدون هدایتگر قرار نداد. \nاین هدایتگران به چهار نحو در کنار هم بودند: \n💠 مِنْ نَبِی مُرْسَلٍ\n۱- از وجود نبی مرسل که برای هدایت مردم فرستاده شد. \n- حضور پیامبر.\n💠 أَوْ کتَابٍ مُنْزَلٍ\n۲- اگر خود پیامبر اولوالعزم نبود کتاب آن پیامبر بود که به واسطه نبی هدایت‌گری می‌شد.\n💠 أَوْ حُجَّةٍ لَازِمَةٍ\n۳- دلیل و حجت الزام‌آور بود. \nاوصیای انبیا بودند، برای هدایت مردم.\n💠 أَوْ مَحَجَّةٍ قَائِمَةٍ\n۴- اگر پیامبری نبود راه و منهاج روشن انبیا بود. همان سنت انبیاء.\nاین چهار حجت، حضور انبیا، اوصیا، ائمه، سنت در کنار آنها قرآن هم هست و مردم را پیش می‌برد. \n💠 رُسُلٌ لَا تُقَصِّرُ بِهِمْ قِلَّةُ عَدَدِهِمْ\nرسولان را به ضعف و کم‌کاری نکشاند تعداد کم مردمان و ایمان‌آورندگان. \nهرگز به‌خاطر نپذیرفتن و مخالفت اکثر مردم عقب‌نشینی نکرده وظیفه خود را سستی نکرده مصراً انجام می‌دادند.\nانبیا با جایگاه ویژه‌ای که انتخاب شدند، صفت بارزی هم داشتند. در عین داشتن علم غیب، تقوا، عصمت و علوم، برجسته‌ترین صفتشان پافشاری‌کردن در مسیر حق بود. \nاز تخریب و ملامت لائم واهمه نداشتند.\n💠 وَ لَا کثْرَةُ الْمُکذِّبِینَ لَهُمْ\nتعداد مکذبین رسولان زیاد بود؛ ولی با همه سختی برای حق و پای حق پایمردی داشتند.\n«صفات شما هم نبی گونه باشد» \n «در مسیر حق قرار بگیرید ولو جاده حق خلوت باشد، از جادهٔ خلوت حق در هراس نباشید، وظیفه خود را انجام دهید چه موفقیت باشد چه نباشد»\nراه شناخت رسولان الهی: \n💠 مِنْ سَابِقٍ سُمِّی لَهُ مَنْ بَعْدَهُ\nالف) هر پیامبر قبلی، پیامبر بعدی را معرفی و آمدن پیامبر بعدی را بشارت می‌داد. \nمردم از این طریق شخص پیامبر بعدی را شناسایی می‌کردند.\n💠 أَوْ غَابِرٍ عَرَّفَهُ مَنْ قَبْلَهُ\nپیامبر باقی‌مانده [غابر] پیامبر حی‌وحاضر، پیامبر قبل و بعد از خود را با اسم، صفات، خصوصیات، مکان تولد، پدر و مادر را بیان می‌کرد.\n\n💠 عَلَی ذَلِک نَسَلَتِ الْقُرُونُ و مَضَتِ الدُّهُورُ\nو سلَفَتِ الاٰباءُ و خلَفَتِ الاَبناءُ\nحلقه خلقت ادامه داشت، نسل‌به‌نسل همین‌طور می‌گردد، قرن به قرن عالم پیش می‌رود، پدران از دنیا رفته و فرزندان جانشین آنان شده . \nاز آدم تا اینکه به دوران نبوت خاصه پیامبر رسید.\n💠 إِلَی أَنْ بَعَثَ اللَّهُ سُبْحَانَهُ مُحَمَّداً [صلی‌الله علیه و آله] رَسُولَ اللَّهِ لِإِنْجَازِ عِدَتِهِ وَ إِتْمَامِ نُبُوَّتِهِ\nدو هدف کلی برای نبوت پیامبر: \nالف) محقق کردن [انجاز] وعده‌های داده شده . \nاز آدم ابوالبشر و همه انبیا عهد گرفت که نبوت شما مقدمه است برای مکتبی که پایدار است و نبوت آن انتهای نبوت است. حال وقت آن وعده رسیده که باید محقق شود.\nب)  جریان نبوت از آدم شروع و به پیامبر خاتم ختم می‌شود.\n💠 مَأْخُوذاً عَلَی النَّبِیینَ مِیثَاقُهُ\nپیامبر آمد، درحالی‌که از تک‌تک انبیا پیمان گرفته بود که به این پیامبر ایمان آورده و آمدن او را تبلیغ کنند. \n \n «هر پیامبری در طول تاریخ به ابتلا و امتحانی گرفتار شد منظور از آن ابتلا شناساندن مقام پیامبر و علی بود. [لقاهُ کلمهَ رحمتِه]»\n💠 مَشْهُورَةً سِمَاتُهُ\nنام پیامبر و نشانه او را در لحظه آمدن همه می‌دانستند. از فرزندان خود بهتر می‌شناختند. \n «کما یَعرفونَ اَبناءَهم»\nیهود خیبر اصالت آنها حجازی نبود؛ اما در منطقه حجاز بودن آنان به دلیل: \nدر کتاب مقدس خود تورات خوانده بودند پیامبری با چنین اوصاف، نام، مکان تولد، و در چه سالی در شبه‌جزیره متولد می‌شود. \nکوچ کردند به آن سرزمین اما در کنار و در حضور پیامبر نتوانستند از آیین خود جدا شوند. \nبه‌خاطر ازدست‌ندادن جایگاه دنیایی خود، پیامبر را انکار کردند درحالی‌که کاملاً دانسته و می‌شناختند.\n💠 کرِیماً مِیلَادُهُ\nمیلاد او کریمانه و عظمت و بزرگواری از میلاد او سرازیر بود\nبتخانه کعبه به هم ریخت، آتشکده‌ها خاموش شد. \nآثار کفر و الحاد به هم ریخت، راه توحید محض با ولادت پیامبر باز شد.\n \nاوضاع اهل زمین قبل از میلاد پیامبر: \n💠 وَ أَهْلُ الْأَرْضِ یوْمَئِذٍ مِلَلٌ مُتَفَرِّقَةٌ\nالف) اهل زمین قبل از میلاد پیامبر، ملل پراکنده، خواسته و اراده‌ها متفرق  \n💠 وَ أَهْوَاءٌ مُنْتَشِرَةٌ وَ طَرَائِقُ مُتَشَتِّتَةٌ\nب) دارای تشتّت مذهب، رویه‌های مختلف.\nبرای شناخت بهتر پیامبر و کارهای صورت‌گرفته از طرف پیامبر باید دوران جاهلیت را شناخت. \nاوج تشتت و انحراف، نه دین و مرام واحد. \nنه راه و هدف واحد. \nاهداف، ادیان، افکار مختلف، هیچ گروهی در کنار هم قرار ندارند. \nتا زمان جاهلیت شناخته نشود کارهای پیامبر شناخته نمی‌شود.\n در خطبه‌ای فرمود: \nزندگی در بدترین سرزمین، بین سنگلاخ و مارهای زهرآلود، آب کدر و نان خشک و سخت، می‌خورید و از دین و تمدن چیزی نمی‌دانستید. دائم در جنگ و خونریزی، خویشان خود را از بین می‌بردید. \nپیامبر از بین شما ابوذر ساخت. ابوذری که بهشت مشتاق او بود تا ابوذر مشتاق بهشت باشد.\n💠 بَینَ مُشَبِّهٍ لِلَّهِ بِخَلْقِهِ\nج) مردم دوران جاهلیت خدا را تشبیه به مخلوقات می‌کردند. \nافراد مشبّهه که هنوز هم هستند؛ اما پیامبر جریان آن را از بین برد.\n💠 أَوْ مُلْحِدٍ فِی اسْمِهِ\nد) در توحید ملحد بودند و نام خدا را دزدیده بر بتان خود گذاشتند. \nبت عزی از نام عزیز خدا ربودند. \nبت لات از نام الله گرفتند.\n💠 أَوْ مُشِیرٍ إِلَی غَیرِهِ\nه) خدا را، خدا نمی‌دانستند، طبیعت خدا بود. \nقائل به اله آب و اله باد بودند.\n💠 فَهَدَاهُمْ بِهِ مِنَ الضَّلَالَةِ\nخدا به برکت وجود پیامبر آن انحراف و ضلالت را هدایت کرد. \nجاهلیت را از جهالت جدا کرد.\n💠 وَ أَنْقَذَهُمْ بِمَکانِهِ مِنَ الْجَهَالَةِ\n به سبب آن جایگاه عظیم پیامبر، خداوند جهال را نجات داد.\n\n💠 ثُمَّ اخْتَارَ سُبْحَانَهُ لِمُحَمَّدٍ صلی‌الله علیه و آله لِقَاءَهُ وَ رَضِی لَهُ مَا عِنْدَهُ\nخدا برای پیامبر اختیار کرد لقا او را. \nآنچه که در نزد خداست وقت آن است به آن مقامات نایل شود.\n💠 وَ أَکرَمَهُ عَنْ دَارِ الدُّنْیا وَ رَغِبَ بِهِ عَنْ مَقَامِ الْبَلْوَی\nگرامی داشت پیامبر را بهنگام کوچ‌دادن از دنیا. \nو خدا علاقه و رغبت نداشت [رَغبَ به] که پیامبر را \nبیش از این در مقام بلوی و امتحان قرار دهد. \nبیش از این در رنج و زحمت دنیا نباشد.\nدو نوع مرگ: \nدلبستگان به دنیا را به‌زور از دنیا می‌برند. متعلقات آنان تمام‌شدنی نیست. \nدنیا را محل لذت و خوشی خود می‌دانند. \n مرگ در مکتب پیامبر: \nگرامی داشتن مرگ و باکرامت کوچ کردن است . [اکرَمَه عن دارِ الدنیا]\n💠 فَقَبَضَهُ إِلَیهِ کرِیماً\nقبض روح کریمانه و در نهایت احترام و اکرام او را برد. \nتولد کریمانه، مرگ کریمانه . \nدر این میان تمام دوران هم کریمانه سپری شد.\nقضیه امامت و اوصیاء: \n💠 وَ خَلَّفَ فِیکمْ مَا خَلَّفَتِ الْأَنْبِیاءُ فِی أُمَمِهَا\nپیامبر به یادگار گذاشته‌اند چیزی را که همه انبیا باقی گذاشتند. \nهمه رسولان بعد خود اوصیایی داشتند. \nچطور پیامبر بعد از خود اوصیایی معرفی نکند. \n💠 إذْ لَمْ یتْرُکوهُمْ هَمَلًا\nهیچ‌کدام از انبیا امت خود را مهمل قرار نداد. \nبه امت خود بی‌اعتنا و بی‌توجه [هَمَلا] نبوده و کار مهملی انجام ندادند. \nهیچ عقل محضی چنین کاری نمی‌کند که زحمت فراوان و سختی برای هدایت مردم کشیده و آنها را بعد از مدتی رها کند.\n💠 بِغَیرِ طَرِیقٍ وَاضِحٍ وَ لَا عَلَمٍ قَائِمٍ\nهرگز علَم برافراشته و امام این راه را رها نکرد. \n « اِنی تارکٌ فیکم الثقلین کتاب‌الله و عترتی» \nهر پیامبری موظف بود بعد از خود پیشوای مردم را معرفی کند. \nاما از میان اهل‌سنت مردی به درشتی گفت: \n «انَّ الرجل لیهجُر» \nبرای انتخاب وصی هذیان می‌گوید.","بخش نهم:\nمتن:\nکتَابَ رَبِّکمْ فِیکمْ مُبَیناً حَلَالَهُ وَ حَرَامَهُ وَ فَرَائِضَهُ وَ فَضَائِلَهُ وَ نَاسِخَهُ وَ مَنْسُوخَهُ وَ رُخَصَهُ وَ عَزَائِمَهُ وَ خَاصَّهُ وَ عَامَّهُ وَ عِبَرَهُ وَ أَمْثَالَهُ وَ مُرْسَلَهُ وَ مَحْدُودَهُ وَ مُحْکمَهُ وَ مُتَشَابِهَهُ مُفَسِّراً [جُمَلَهُ] مُجْمَلَهُ وَ مُبَیناً غَوَامِضَهُ، بَینَ مَأْخُوذٍ مِیثَاقُ عِلْمِهِ وَ مُوَسَّعٍ عَلَی الْعِبَادِ فِی جَهْلِهِ وَ بَینَ مُثْبَتٍ فِی الْکتَابِ فَرْضُهُ وَ مَعْلُومٍ فِی السُّنَّةِ نَسْخُهُ وَ وَاجِبٍ فِی السُّنَّةِ أَخْذُهُ وَ مُرَخَّصٍ فِی الْکتَابِ تَرْکهُ وَ بَینَ وَاجِبٍ [لِوَقْتِهِ] بِوَقْتِهِ وَ زَائِلٍ فِی مُسْتَقْبَلِهِ، وَ مُبَاینٌ بَینَ مَحَارِمِهِ مِنْ کبِیرٍ أَوْعَدَ عَلَیهِ نِیرَانَهُ أَوْ صَغِیرٍ أَرْصَدَ لَهُ غُفْرَانَهُ وَ بَینَ مَقْبُولٍ فِی أَدْنَاهُ [وَ] مُوَسَّعٍ فِی أَقْصَاهُ.\nوَ فَرَضَ عَلَیکمْ حَجَّ بَیتِهِ الْحَرَامِ الَّذِی جَعَلَهُ قِبْلَةً لِلْأَنَامِ یرِدُونَهُ وُرُودَ الْأَنْعَامِ وَ [یوْلَهُونَ] یأْلَهُونَ إِلَیهِ [وَلَهَ] وُلُوهَ الْحَمَامِ وَ جَعَلَهُ سُبْحَانَهُ عَلَامَةً لِتَوَاضُعِهِمْ لِعَظَمَتِهِ وَ إِذْعَانِهِمْ لِعِزَّتِهِ وَ اخْتَارَ مِنْ خَلْقِهِ سُمَّاعاً أَجَابُوا إِلَیهِ دَعْوَتَهُ وَ صَدَّقُوا کلِمَتَهُ وَ وَقَفُوا مَوَاقِفَ أَنْبِیائِهِ وَ تَشَبَّهُوا بِمَلَائِکتِهِ الْمُطِیفِینَ بِعَرْشِهِ یحْرِزُونَ الْأَرْبَاحَ فِی مَتْجَرِ عِبَادَتِهِ وَ یتَبَادَرُونَ عِنْدَهُ مَوْعِدَ مَغْفِرَتِهِ جَعَلَهُ سُبْحَانَهُ وَ تَعَالَی لِلْإِسْلَامِ عَلَماً وَ لِلْعَائِذِینَ حَرَماً [وَ] فَرَضَ حَقَّهُ وَ أَوْجَبَ حَجَّهُ وَ کتَبَ [عَلَیهِ] عَلَیکمْ وِفَادَتَهُ فَقَالَ سُبْحَانَهُ \"وَ لِلَّهِ عَلَی النَّاسِ حِجُّ الْبَیتِ مَنِ اسْتَطاعَ إِلَیهِ سَبِیلًا وَ مَنْ کفَرَ فَإِنَّ اللَّهَ غَنِی عَنِ الْعالَمِینَ\".\nترجمه:\nاو (پیامبر اسلام) کتاب پروردگار شما را در میانتان به یادگار گذاشت درحالی‌که حلال و حرام خدا و واجبات و مستحبّاتش را بیان کرده بود و همچنین ناسخ و منسوخ آن و مباح و ممنوع آن را روشن نمود، خاص و عام آن را توضیح داد و پندها و مثل‌هایش را روشن ساخت و مطلق و مقید آن را بیان کرد و محکم و متشابه آن را معین فرمود و مجمل آن را تفسیر و غوامض و پیچیدگی‌هایش را (با سخنان مبارکش) تبیین نمود. این در حالی بود که معرفت و فراگیری بخشی (مهم) از آن (بر همه واجب بود و) پیمانش از همه گرفته شده بود و بخش دیگری، ناآگاهی از آن برای بندگان مجاز بود (مانند حروف مقطّعه قرآن که به‌صورت اسرارآمیزی ذکر شده است) و در حالی بود که قسمتی از آن در این کتاب الهی (برای مدّت محدودی) واجب شده و نسخ آن در سنّت پیامبر معلوم گشته بود و نیز احکامی بود که در سنّت پیامبر (صلی‌الله علیه و آله) عمل به آن واجب بود؛ ولی در کتاب خدا ترک آن اجازه داده شده بود و احکامی که در بعضی از اوقات، واجب ولی در زمان بعد زایل شده بود.\nاینها همه در حالی است که انواع محرمات آن از هم جدا شده، از گناهان کبیره‌ای که خداوند وعده آتش خود را بر آن داده تا گناهان کوچکی که غفران و آمرزش خویش را برای آن مهیا ساخته است و نیز احکامی که انجام کمش مقبول و مراتب بیشترش مجاز و مردم از جهت آن در وسعت بودند (آری خداوند چنین کتابی را با این جامعیت و وسعت و دقّت بر پیامبرش نازل کرد و او بعد از رحلتش آن را در میان امّت به یادگار گذارد).\n\n(خداوند) حجّ بیت‌الله الحرام (خانه گرامی و محترمش) را بر شما واجب کرده است، همان خانه‌ای که آن را قبله مردم قرار داده است که همچون تشنه‌کامانی که به آبگاه می‌روند به‌سوی آن می‌آیند و همچون کبوتران به آن پناه می‌جویند.\nخداوند، حج را علامت فروتنی در برابر عظمتش قرار داده و نشانه‌ای از اعتراف به عزّتش و از میان خلق خود، شنوندگانی را برگزیده که دعوت او را اجابت کرده و سخنانش را تصدیق نموده‌اند و در جایگاه پیامبران الهی وقوف کرده و به فرشتگانی که بر گرد عرش الهی می‌گردند، شبیه می‌شوند. سودهای فراوانی در این تجارت‌خانه عبادت الهی به دست آورده و به‌سوی میعادگاه آمرزش و مغفرتش می‌شتابند. خداوند متعال این خانه را پرچم (علامتی) برای اسلام قرار داده و حرم امنی برای پناه‌جویان.\nادای حقّ آن را واجب شمرده و حجّ آن را لازم کرده، و بر همه شما زیارت‌خانه‌اش را به طور دسته‌جمعی مقرّر داشته و فرموده است: برای خدا بر همه مردم است که آهنگ خانه او کنند آنها که توانایی رفتن به‌سوی آن را دارند و هر کس کفر ورزد (و حجّ را ترک کند به خود زیان رسانده) خداوند از همه جهانیان بی‌نیاز است. \nتفسیر:\nقرآن و حج: \n\n💠 کتَابَ رَبِّکمْ فِیکمْ مُبَیناً حَلَالَهُ وَ حَرَامَهُ وَ فَرَائِضَهُ\n» عطف به خلَف فیکم «\n پیامبر در میان مردم جانشینی از ائمه و کتاب خدا، قرآن را باقی گذاشت. \nقرآن با جامعیت تمام حلال و حرام آن را بیان کرد. \nهم فرائض و هم نوافل را ذکر کرد.  \n\n💠 نَاسِخَهُ وَ مَنْسُوخَهُ\nناسخ و منسوخ قرآن را تبیین کرد. \nناسخ: حکم جدید قرآن که آمد \nمنسوخ: حکم قبل از بین می‌رود.\nآیه منسوخ: \n» یا ایها الذین امنو اذا ناجیتمُ الرسول فقَدموا بین یدی نجویٰکم صدقه مجادله - ۱۲» \n مؤمنین در گفتگوی آهسته با پیامبر صدقه دهید. جز امیرالمؤمنین کسی به آن عمل نکرد. \nاین آیه بعدها منسوخ شد.\n\n💠 وَ رُخَصَهُ وَ عَزَائِمَهُ وَ خَاصَّهُ وَ عَامَّهُ\nآیات رخصت و واجب را، خاص و عام را بیان کرد.\nآیه رخصت:\n «و اذا حَلَلتُم فَاصطادوا مائده - ۲» \nاز احرام خارج شدید صید کنید . \nاین رفتن به صید به معنای رخصت دادن است. \nصیدکردن جایز است، رفتن به صید وجوب نیست. \nآیه عزائم: \n» و اذا ضرَبتُم فی الارضِ فلیس علیکم جناحٌ اَن تَقصُروا منَ الصلوٰهِ نسل - ۱۰۱» \nدر سفر عیبی نیست نماز شکسته بخوانید، طاهر آیه نشان می‌دهد که دلبخواهی است. \nظاهر قرآن چیزی است؛ ولی عزم آن چیز دیگری‌ست . \nو فهم آن را پیامبر بیان می‌کند.\nآیه خاصه: \nاحکام اختصاصی قرآن، مانند حج واجب می‌شود به‌شرط استطاعت. روزه واجب می‌شود منوط بر توانایی. \nاما آیات عامه: \nنماز واجب می‌شود درهرحال و شرایطی که باشد \nرفتن به حج را پیامبر بیان می‌کند که چه کسانی باید بروند. \nاین کلمات در علوم قرآنی کاربرد زیادی دارد.\n\n \n💠 وَ عِبَرَهُ وَ أَمْثَالَهُ\nپیامبر عبرت‌ها و مثال‌های قرآن را بیان کرد. \n آیه عبرت: \nدانستن اموری که در زندگی می‌تواند کاربرد داشته باشد. عبرت‌ها در زندگی قابل‌بازسازی هستند. \n وقتی اقوام ظالم گذشته دچار عذاب شدند، دیدن آن و عبور از آن و ورود آن به حال کنونی زندگی عبرت است. \nآیه مثال: \nدر مثال‌آوردن قرآن اهدافی در پشت آن منظور است که مسائل سنگین علمی و غیبی را توضیح می‌دهد \n«انَ الله لا یَستَحیی اَن یَضربَ مثلاً ما بَعوضَهً فما فوق‌ها بقره - ۲۵» \nخدا ابایی ندارد از اینکه مثال پشه یا بزرگ‌تر از آن را بزند. \nبا مثال نام اشخاص در قرآن برده می‌شود و تبیین آن باوجود مقدس پیامبر صلی‌الله علیه واله است.\n\n💠 وَ مُرْسَلَهُ وَ مَحْدُودَهُ\nآیات مطلق و مقید قرآن را ذکر می‌کند. \nآیه مرسل: \n «اَحلَّ الله البیعَ و حرَّمَ الربوا بقره - ۲۷۵» \nبه‌طورکلی بیع و معامله را حلال کرده. \nآیه کلی و مطلق آمده. \nآیه محدود و مقید: \nبیع و تجارتی که هر دو طرف راضی باشند حلال است. نه اینکه یک طرف از معامله خشنود باشد و دیگری متضرر. \nآیه اول عام را بیان کرد \nآیه دوم تخصیص و قید زد.\n\n\n💠 وَ مُحْکمَهُ وَ مُتَشَابِهَهُ\nآیات محکم: \n «اَقیموالصلوٰه؛ قل هو الله احد» \nمعنای دیگری برای آن متصور نیست. \nآیات متشابه: \n «ثم استویٰ علی العرش سجده -  ۴» \n «الیٰ رب‌ها ناظِره قیٰمه - ۲۳» \nآیات متشابه را می‌شود از آن چندمعنا گرفت. \nخداوند جسم نیست بر روی عرش باشد \nجسم نیست نظاره‌گر باشد.\n\n💠 مُفَسِّراً [جُمَلَهُ] مُجْمَلَهُ وَ مُبَیناً غَوَامِضَهُ\nمجهولات قرآن را تفسیر کرد. \nامر شد به اقامه صلوٰة، این نماز چگونه و با چه کیفیت، چه تعداد، چه سوره‌هایی، پیغمبر همه را مشخص کرد و مجمل‌ها را مفسِراً بیان کرد.\nو پیچیدگی قرآن [غوامض] را بیان فرمود. \nحروف مقطعه از ظواهر قرآن و سر، باطن قرآن و امور سنگین را آشکار کرد.\n\n💠 بَینَ مَأْخُوذٍ مِیثَاقُ عِلْمِهِ\nخدای متعال برای همه مردم، یادگیری برخی نکات قرآن را اصرار ورزیده، \nبعضی امور را همه باید یاد بگیرند؛ مانند علم توحید. مسلمان باید اصل توحید و شرک را بداند. گرچه ظرایف آن را نداند. \nاصل علم غیب را بداند و اینکه خدا عالم الغیب است.\n\n💠 وَ مُوَسَّعٍ عَلَی الْعِبَادِ فِی جَهْلِهِ\nدر یادگیری برخی اصرار دارد، در برخی موارد هم جاهل باشند موردی نیست. \nسوخت‌وسوز جهنم، ظرایف بهشت و کیفیت نعمت‌های بهشت چگونه است! \nچیزی که بر ندانستن آن منعی نشده.\n\n💠 وَ مَعْلُومٍ فِی السُّنَّةِ نَسْخُهُ\nکتاب قرآن آیه معلوم را ثابت کرد و سنت نبوی آن آیه را نسخ کرد. \n «فاَمسِکوهنَ فی البیوت حتیٰ یَتَوفیٰهن اَو یَجعَلَ الله لهنَّ سبیلا نساء - ۱۵» \n زنان در حصن همسر مرتکب عمل شنیع زنا شدند حبس در خانه می‌شدند تا بمیرند. \nیا اینکه خدا راه دیگری بر آنان قرار دهد. \nو پیامبر آمد بحث رجم را مطرح کرد. \nحبس ابد زنان برداشته شد.\n\n 💠و وَاجِبٍ فِی السُّنَّةِ أَخْذُهُ \nیک سنتی واجب بود که آیه قرآن آن را ترخیص داد و مجاز شمرد\nدر ابتدای اسلام روزه‌داران تا زمان بیداری حق خوردن داشتند. اگر بخواب می‌رفتند بعد از خواب حق خوردن نبود، حتی هر ساعتی بود. \nآیه آمد این سنت نبوی را نسخ کرد و وقت خوردن تا اذان صبح مجاز شمرده شد. \n «حتیٰ یَتبَینَّ لکمُ الخیطُ الاَبیضُ منَ الخیطِ الاسوَدِ منَ الفجر. بقره -۱۸۷»\nنسخ، حکم ثابت توسط حکم جدید از بین می‌رود. \nحکم تغییر قبله از بیت المقدس به سمت کعبه.\n\nفلسفه نسخ: \nجاهلان قائلند چون خدا نمی‌دانست چه اتفاقی می‌افتد حکمی داد و بعد حکم را عوض کرده. \nدرحالی‌که خداوند بر اساس فلسفه و حکمت‌هایی، ابتدا کعبه را قبله قرار نداد . \nکعبه از ابتدا موردتوجه همه بوده؛ ولی فعلاً برای قبله بتکده است، باید تطهیر شود. \nبه‌خاطر مسائلی قبله نیست تا مردم متوجه اشتباه خود شوند. \nحکمی که زمان خاصی دارد بعد عوض می‌شود.\n\n💠 وَ مُرَخَّصٍ فِی الْکتَابِ تَرْکهُ وَ بَینَ وَاجِبٍ [لِوَقْتِهِ] بِوَقْتِهِ\nآیات برخی زمان خاص دارد مثل ماه مبارک رمضان. تا فردی دران ماه بیهوش است تکلیف روزه ندارد. \n «و من کان منکم مریضاَ اوَ سفرً فعدهٌ من ایامً اُخَر بقره - ۱۹۶» \nولی امربه‌معروف زمان بردار نیست، هر ماهی باشد واجب است.\n\n💠 وَ مُبَاینٌ بَینَ مَحَارِمِهِ\nقران بین چیزهایی که حرام شده فرق گذاشت. \n «و من یَقتُل مومناً متَعَمداَ فجزاوهُ جهنم نسل - ۹۳» \nقتل عمد گناه کبیره که جزای او جهنم است. \nتبیین کرد بعضی حرام‌ها کبیره است.\n\n💠 مِنْ کبِیرٍ أَوْعَدَ عَلَیهِ نِیرَانَهُ\nمعیار و ملاک کبیره را امیرالمؤمنین بیان می‌دارد: \nآنچه را در قرآن کریم وعدهٔ عذاب داده باشد، عذاب حتمی باشد گناه کبیره می‌شود\n\n💠أَوْ صَغِیرٍ أَرْصَدَ لَهُ غُفْرَانَهُ\nخدا فراهم کرده { ارصَد } مقدمات غفران گناه صغیره را. \n «انَ ربکَ لذو مغفرهٕ للناس علیٰ ظلمِهِم یونس - ۶»\n\n💠 وَ بَینَ مَقْبُولٍ فِی أَدْنَاهُ [وَ] مُوَسَّعٍ فِی أَقْصَاهُ\nخدا بین احکام و اعمال به حداقل راضی آن راضی است. کوچک‌ترین قسمت آن را قبول می‌کند. مانند نمازی که حضور قلب هم ندارد. \n آن حداقل را قبول می‌کند. مانند: \n «فاقرَؤا ما تَیَسَرَ منَ القرانِ مزمل - ۲۰» \nبتواند بیش از آن رعایت کند [موسع] بهتر است.\n\nدر بیان حج: \n\n💠 وَ فَرَضَ عَلَیکمْ حَجَّ بَیتِهِ الْحَرَامِ الَّذِی جَعَلَهُ قِبْلَةً لِلْأَنَامِ\nکعبه جایگاه مقدس، و حج بیت‌الله را واجب کرد و قبله تمام مخلوقات قرار داد. \nکعبه توجه همه انسان‌هاست چه کافر چه مؤمن، \nخیروبرکت از آنجا نشئت می‌گیرد.\n\n💠 یرِدُونَهُ وُرُودَ الْأَنْعَامِ\nامت اسلام باید مانند چهارپایان تشنه‌لب به سمت آب از هم سبقت گرفته تا به چشمه برسند [یردون] باشند. به سمت کعبه سرعت بگیرند.\n\n💠 وَ [یوْلَهُونَ] یأْلَهُونَ إِلَیهِ [وَلَهَ] وُلُوهَ الْحَمَامِ\nمانند کبوتری که بازگشت به آشیانه را علاقه‌مند است اشتیاق داشته و له کعبه و حج داشته باشند.\n\n💠 وَ جَعَلَهُ سُبْحَانَهُ عَلَامَةً لِتَوَاضُعِهِمْ لِعَظَمَتِهِ وَ إِذْعَانِهِمْ لِعِزَّتِهِ\nخدا حج را واجب کرد به دو غرض: \nالف) تواضع شما را بسنجد. \nنشانه برای تواضع در مقابل عظمت خود قرار داد. \nب) با وجوب اعمال حج به عزت خدا اعتراف شود. \nدر حج تمام القاب فروریخته، سر به زیر، مانند انسان درون قبر، همه یکدست، تسلیم، مثل هم به عزت خدا معترف شوند. \nحج فلسفهٔ خودسازی است.\n\n💠وَ اخْتَارَ مِنْ خَلْقِهِ سُمَّاعاً أَجَابُوا إِلَیهِ دَعْوَتَهُ\nخدا انتخاب کرد از خلقش، کسانی که دعوت خدا را شنیدند [سُماع] و اجابت کردند. \nحج استطاعت دارد، هرکس پول دارد حج نمی‌رود، هر کسی سالم است نمی‌رود، حج اختیاری و انتخاب خداست. حج یک رزق است و توفیق.\n💠 وَ صَدَّقُوا کلِمَتَهُ وَ وَقَفُوا مَوَاقِفَ أَنْبِیائِهِ\nخدا اختیار کرد برای حج، آنهایی که کلام حق را تصدیق کردند. \nحج موقف انبیا عظام و عبادتگاه آنان است.\nامام صادق ع:  هزاران سال قبل از آدم موجوداتی بودند که حج انجام می‌دادند، قبل از هبوط آدم سابقه داشته.\n\n💠 وَ تَشَبَّهُوا بِمَلَائِکتِهِ الْمُطِیفِینَ بِعَرْشِهِ\nشباهت پیدا کردند به ملائکی که گرداگرد عرش الهی طواف می‌کنند. \nامام صادق (ع): \nسؤال شد از نام کعبه!!! \n فرمود: چون مکعب است. \nچرا دایره ساخته نشده!! \nفرمود: کعبه برگرفته و مانند عرش است که ملائک آن را طواف می‌کنند. \nآنجا مکان و شیء نیست. تسبیحات اربعه است . \nتسبیح همه‌کاره است. تسبیح چهارگوشه دارد مکعب است. این کعبه نمونه‌ای از آن است. \nباطن حج ولایت است . \nطواف بر سنگ و آهن نیست. \nفرمود علی جان تو به منزله کعبه هستی . \nکعبه بر کسی وارد نمی‌شود . \nمردم باید دور کعبه بگردند. \nعلی جان تو به منزله کعبه برای مردم هستی، مردم باید دودستی حکومت را به تو تحویل بدهند.\n\n\n\n\n\n\n\n💠 یحْرِزُونَ الْأَرْبَاحَ فِی مَتْجَرِ عِبَادَتِهِ\nعبادت و اسرار حج یک سود سراسر محض است که در آن ضرر وجود ندارد. \nمردمی که انتخاب می‌شود، سودهایی  [ارباح] در این تجارت به دست می‌آورند. \nیک سود مسائل اقتصادی حج، \nسود مسائل سیاسی حج، \nسودهای تجارت را حفظ می‌کنند [یحرزون] در بازرگانی بندگی و عبادت [متجَر]\n\n💠 وَ یتَبَادَرُونَ عِنْدَهُ مَوْعِدَ مَغْفِرَتِهِ\nبه‌سرعت به سمت میعادگاه آمرزش الهی حرکت می‌کنند. \nخدا به مغفرت خوانده است و بساط بخشش و آمرزش فراهم شده است.\n\n💠 جَعَلَهُ سُبْحَانَهُ وَ تَعَالَی لِلْإِسْلَامِ عَلَماً وَ لِلْعَائِذِینَ حَرَماً\nخدا حج را یک نماد و علَم برای اسلام قرار داد. \nبرای پناه آوردگان مکان آسایش و هیچ حق تعرض بر آنان نیست. \nحج می‌تواند نیرو کشف کند بر ضد استکبار.\nدشمنان فهمیدند تا وقتی حج در بین مسلمان‌ها بدون اختلاف بر پا شود قدرت عظیمی خواهند داشت؛ لذا تا توانستند اختلاف و انحراف ایجاد کردند. در حج اختلافی هم چنین نعمت و سودهایی بر نمی‌آید.\n\n💠 فَرَضَ حَقَّهُ وَ أَوْجَبَ حَجَّهُ وَ کتَبَ [عَلَیهِ] عَلَیکمْ وِفَادَتَهُ\nبرمسلمین حج و مناسک را واجب، و حق حج به دست مسلمین باید ادا شود. \nو واجب کرد که گروه‌گروه [وفاده] به حج عازم شوند.\n\n💠فَقَالَ سُبْحَانَهُ \"وَ لِلَّهِ عَلَی النَّاسِ حِجُّ الْبَیتِ مَنِ اسْتَطاعَ إِلَیهِ سَبِیلًا وَ مَنْ کفَرَ فَإِنَّ اللَّهَ غَنِی عَنِ الْعالَمِینَ\". آل‌عمران ۹۴\nحج حق خداست بر مردم و ادای آن حق واجب است. هرکس توانایی دارد بر انجام حج، و هرکه کافر باشد، به خدا زیانی ندارد؛ چون خدا نیازی ندارد و غنی بالذات است.\n یک سرّ حج قربانی است و قربانی حج باید سالم بوده، معیوب و مجروح نباشد. \nقربانی نفس، هواوهوس، کبر، شهوت است. \nدر اوج جوانی سر شهوت بریده شود ارزشمند است."]});
